INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('dfa900e50f7ab1eb6fb3','Amedex 2023.pdf','1854','Mixed/Unclassified','A 12 year-old boy is brought to the emergency department by his mother with complaints of cough
and wheezing. He has had previous episodes in the past, and has not any specific treatment so far.
On examination, he has a respiratory rate of 40 breaths per minute and a temperature of 37.5°C. On
chest auscultation, widespread wheeze is noted bilaterally. The rest of the exam is inconclusive.
Which one of the following is most likely to make a diagnosis now and in the emergency setting?','{"A":"CT scan of the chest.","B":"Chest X-ray (CXR).","C":"Spirometry.","D":"Improvement with salbutamol.","E":"Measurement of peak expiratory flow (PEF)."}','D','The scenario is typical for an exacerbation of a previously-undiagnosed asthma. Asthma is the
most common cause cough and wheezing in children.
By definition, asthma is reversible inflammatory response of the bronchial tree triggered by factors
such as allergens, cold, exercise, stress, noxious inhalants, dust mite, etc. Reversibility and
symptom relief after administration of bronchodilators (e.g. inhaled salbutamol) is the key issue in
diagnosis of asthma.
Imaging studies such as plain chest X-ray (option B) or CT scan (option A) are not routinely used
for diagnosis of asthma, unless bases on clinical grounds, an alternative diagnosis other than
asthma is considered.
Spirometry (option C) can help in diagnosis by showing a reversible obstructive pattern; however, it
is of little value during an exacerbation of asthma when patient cannot efficiently follow the
instructions such as taking a very deep breath, or blowing with the maximum force they can. In
patients with intermittent asthma, pulmonary function test using spirometry may be inconclusive if
carried out in between attacks. If so, bronchoconstriction is induced by metacholine (metacholine
challenge test). A bronchodilator is then administered to see whether this is reversible. Reversibility
suggests asthma with high certainty.
PEF (option E) is a valuable tool to use for monitoring the response to treatment e.g. inhaled
salbutamol. Increasing values read by PEF indicates appropriate response to treatment. The
question though asks about the best method for diagnosis now in the acute setting the patient has
presented with not how to assess the response to treatment in which case PEF would be the
correct answer.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-a3a008c66246","duplicate_sources":[{"record_id":"dfa900e50f7ab1eb6fb3","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1854,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"dfa900e50f7ab1eb6fb3","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1854,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 12 year-old boy is brought to the emergency department by his mother with complaints of cough\nand wheezing. He has had previous episodes in the past, and has not any specific treatment so far.\nOn examination, he has a respiratory rate of 40 breaths per minute and a temperature of 37.5°C. On\nchest auscultation, widespread wheeze is noted bilaterally. The rest of the exam is inconclusive.\nWhich one of the following is most likely to make a diagnosis now and in the emergency setting?","options":{"A":"CT scan of the chest.","B":"Chest X-ray (CXR).","C":"Spirometry.","D":"Improvement with salbutamol.","E":"Measurement of peak expiratory flow (PEF)."},"source_answer":"D","source_explanation":"The scenario is typical for an exacerbation of a previously-undiagnosed asthma. Asthma is the\nmost common cause cough and wheezing in children.\nBy definition, asthma is reversible inflammatory response of the bronchial tree triggered by factors\nsuch as allergens, cold, exercise, stress, noxious inhalants, dust mite, etc. Reversibility and\nsymptom relief after administration of bronchodilators (e.g. inhaled salbutamol) is t