INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('c7c671cb5729a5d46330','Amedex 2023.pdf','1863','Mixed/Unclassified','A 30-year-old woman, recently migrated from China to Australia, is undergoing a health
assessment. Before coming to Australia, she had been working in a cotton mill for 18 months and
describes that upon start of the workweek she developed chest tightness, shortness of breath,
cough, and wheeze. These symptoms eased up through the week, were almost absent in
weekends, and started over the next workweek. Physical examination including a thorough
examination of the chest and lungs are inconclusive. Her chest x-ray is normal as is her pulmonary
function tests. Which one of the following could be the most likely diagnosis?','{"A":"Anxiety.","B":"Berylliosis.","C":"Byssiniosis.","D":"Silicosis.","E":"Occupational asthma."}','C','The clinical picture given in this scenario is highly suggestive of byssinosis as the most likely
diagnosis. Byssinosis is a type of occupational lung disease almost exclusively seen in workers
who are in contact with unprocessed raw cotton especially those who are exposed to open bales of
cotton or work in cotton spinning or carding rooms.
Often, byssinosis occurs in workers with at least 10 years of exposure, but it can also develop
acutely in a matter of hours or days.
The etiology of the condition is suggested to be a bacterial endotoxin in cotton dust. The endotoxin
results in bronchoconstriction acutely, and in longer term exposures, chronic bronchitis and gradual
decreases in pulmonary function, particularly in genetically susceptible people. Cotton dust does
not cause chronic obstructive lung disease as (COPD) as previously thought.
Symptoms are chest tightness and dyspnea that reduce with repeated exposure. Symptoms
develop on the first day of work after a weekend or vacation and diminish or disappear by the end
of the week. With repeated exposure over a period of years, chest tightness tends to return and
persist through midweek and occasionally to the end of the week or as long as the person
continues to work. This typical temporal pattern distinguishes byssinosis from asthma (option E);
however, symptoms are relieved by asthma medications. Physical findings of acute exposure are
tachypnea and wheezing while with chronic exposure crackles can be a finding.
During attacks, pulmonary function tests show characteristic patterns of reversible air flow
obstruction and reduced vital capacity, especially if measured during the first work shift. Other than
such times, pulmonary function tests are inconclusive unless chronic disease has set in, in which
case a restrictive pattern is more likely. Hyperresponsiveness to methacholine is often observed.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-93bf90e0f6cb","duplicate_sources":[{"record_id":"c7c671cb5729a5d46330","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1863,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"c7c671cb5729a5d46330","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1863,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 30-year-old woman, recently migrated from China to Australia, is undergoing a health\nassessment. Before coming to Australia, she had been working in a cotton mill for 18 months and\ndescribes that upon start of the workweek she developed chest tightness, shortness of breath,\ncough, and wheeze. These symptoms eased up through the week, were almost absent in\nweekends, and started over the next workweek. Physical examination including a thorough\nexamination of the chest and lungs are inconclusive. Her chest x-ray is normal as is her pulmonary\nfunction tests. Which one of the following could be the most likely diagnosis?","options":{"A":"Anxiety.","B":"Berylliosis.","C":"Byssiniosis.","D":"Silicosis.","E":"Occupational asthma."},"source_answer":"C","source_explanation":"The clinical picture given in this scenario is highly suggestive of byssinosis as the most likely\ndiagnosis. Byssinosis is a type of occupational lung disease almost exclusively seen in workers\nwho are in contact with unprocessed raw cotton especially those who ar