INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('18ab53fa5b5d3e41d3ec','Amedex 2023.pdf','1866','Mixed/Unclassified','Ashley is brought to your clinic by his mother. He is a 9-year-old boy, who has been diagnosed with
intermittent asthma two years ago. He is on inhaled salbutamol on an as-needed basis. His mother
mentions that he has had to use his medication more frequently recently. Moreover, he has
developed night coughs at least 2-3 times a week. Examination reveals diffuse wheezing over the
lung fields. Which one of the following would be the most appropriate next step in management?','{"A":"Start him on inhaled fluticasone and salmeterol.","B":"Start him on inhaled fluticasone.","C":"Start him on a 14-day course of oral steroids.","D":"Start him on montelukast.","E":"Start him on sodium cromoglycate."}','D','This child had been diagnosed with mild intermittent asthma and started on a short-acting β2
agonist (salbutamol) on an as-needed basis, but his asthma is poorly controlled. Once adherence
to therapy and inappropriate medication use are excluded as the possible causes of
unresponsiveness to treatment, the next step would be a 2- to 4-week course of montelukast. If the
symptoms improve, montelukast should be continued; otherwise, it should be replaced with the
lowest effective dose of inhaled corticosteroids as the most appropriate next step in
management. Montelukast is used to spare the child from inhaled corticosteroids and their
potential adverse effects if there is a response.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"359","duplicate_group_id":"exact-0becf7b8e486","duplicate_sources":[{"record_id":"18ab53fa5b5d3e41d3ec","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1866,"source_qid":"359"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"18ab53fa5b5d3e41d3ec","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1866,"source_qid":"359","domain_hint":"Mixed/Unclassified","stem":"Ashley is brought to your clinic by his mother. He is a 9-year-old boy, who has been diagnosed with\nintermittent asthma two years ago. He is on inhaled salbutamol on an as-needed basis. His mother\nmentions that he has had to use his medication more frequently recently. Moreover, he has\ndeveloped night coughs at least 2-3 times a week. Examination reveals diffuse wheezing over the\nlung fields. Which one of the following would be the most appropriate next step in management?","options":{"A":"Start him on inhaled fluticasone and salmeterol.","B":"Start him on inhaled fluticasone.","C":"Start him on a 14-day course of oral steroids.","D":"Start him on montelukast.","E":"Start him on sodium cromoglycate."},"source_answer":"D","source_explanation":"This child had been diagnosed with mild intermittent asthma and started on a short-acting β2\nagonist (salbutamol) on an as-needed basis, but his asthma is poorly controlled. Once adherence\nto therapy and inappropriate medication use are excluded as the possible causes of\nunresponsiveness to treatment, the next step would be a 2- to 4-week course of montelukast. If the\nsymptoms improve, montelukast should be continued; otherwise, it should be replaced with the\nlowest effective dose of inhaled corticosteroids as the most appropriate next step in\nmanagement. Montelukast is used to spare the child from inhaled corticosteroids and their\npotential adverse effects if there is a response.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","asthma","dose","management","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"0becf7b8e486f294df44ba9f1a0b08f3eb49a969","duplicate_group_id":"exact-0becf7b8e486","duplicate_sources":[{"record_id":"18ab53fa5b5d3e41d3ec","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1866,"source_qid":"359"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
