INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('dc3dead325d1448262d8','Amedex 2023.pdf','1867','Mixed/Unclassified','A 55-year-old man presents to your practice with complaints of shortness of breath and cough for
the past 2 months. After initial evaluation, you arrange a pulmonary function test for him, the result
of which is as follows:
FVC (forced vital capacity) = 60% (normal >80% of predicted)
FEV1 (Forced expiratory volume in 1 second) = 35% predicted (normal >80% of predicted)
FEV1/FVC = 0.58
Which one of the following is the most likely diagnosis?','{"A":"Obstructive pulmonary disease.","B":"Restrictive pulmonary disease.","C":"Obesity.","D":"Myasthenia gravis.","E":"Concurrent obstructive and restrictive lung pathologies."}','E','Forced vital capacity (FVC) is the amount of air that a patient can exhale in a single expiration after
a deep inspiration, no matter how long it takes. FVC is diminished (less than 80% predicted) in
restrictive pulmonary disease and severe obstructive diseases.
Forced expiratory volume in the first second (FEV1) reflects the airway flow; therefore it is expected
to be within normal range in patients with restrictive pulmonary disease, as there is no obstruction
against the flow. FEV1 is diminished in obstructive diseases.
The best indicator of obstructive vs. restrictive pulmonary disease is the FEV1/FVC ratio (normal
0.75 – 0.85). In obstructive diseases, the FEV1 is decreased, but the FVC remains unaffected or
mildly decreased (unless there is severe obstruction); hence, the ratio will decrease. In restrictive
diseases both FEV1 and FVC decrease so the ratio is expected to be normal or even slightly
increased.
When the FEV1/FVC is reduced, the next step would be looking at the FVC. If FVC is normal a pure
obstructive disease (e.g. asthma) is the expected underlying cause, whereas a decreased FVC is
either due to a reduction in lung volume (e.g. concomitant restrictive lung disease), namely mixed
pattern, or severe obstruction that can result in increased residual volume and consequently a
decreased vitally capacity.
Since this patient has decreased FEV1, FEV1/FVC, and FVC, a severe obstructive disease or a mix
obstructive/restrictive lung pathology is the best explanation and the correct option.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-97d362b9be39","duplicate_sources":[{"record_id":"dc3dead325d1448262d8","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1867,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"dc3dead325d1448262d8","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1867,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 55-year-old man presents to your practice with complaints of shortness of breath and cough for\nthe past 2 months. After initial evaluation, you arrange a pulmonary function test for him, the result\nof which is as follows:\nFVC (forced vital capacity) = 60% (normal >80% of predicted)\nFEV1 (Forced expiratory volume in 1 second) = 35% predicted (normal >80% of predicted)\nFEV1/FVC = 0.58\nWhich one of the following is the most likely diagnosis?","options":{"A":"Obstructive pulmonary disease.","B":"Restrictive pulmonary disease.","C":"Obesity.","D":"Myasthenia gravis.","E":"Concurrent obstructive and restrictive lung pathologies."},"source_answer":"E","source_explanation":"Forced vital capacity (FVC) is the amount of air that a patient can exhale in a single expiration after\na deep inspiration, no matter how long it takes. FVC is diminished (less than 80% predicted) in\nrestrictive pulmonary disease and severe obstructive diseases.\nForced expiratory volume in the first second (FEV1) reflects the airway flow; therefore it is expected\nto be wi