INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('622ba69e065c96096013','Amedex 2023.pdf','1869','Mixed/Unclassified','A 35-year-old man with history of sore throat three weeks ago, presents to the Emergency
Department with a puffy face and decreased urine output for the past 48 hours. On examination, he
has a blood pressure of 160/120 mmHg. His face is swollen especially in the periorbital area. On
lung auscultation, bilbasal crepitations are heard. Which one of the following is correct regarding
his condition?','{"A":"Hematuria is a grave prognostic factor.","B":"He is at immediate risk of death from left ventricular failure.","C":"Increase in oral intake will result in diuresis.","D":"If there is renal tenderness, a renal biopsy should be performed.","E":"Dialysis is contraindicated during the acute phase of the illness."}','B','Facial edema, hypertension and oliguria are strong pointers towards glomerulonephritis. With the
sore throat in the history, post-streptococcal glomerulonephritis (PSGN) is the most likely cause of
this presentation.
PSGN is induced by infection with specific nephritogenic strains of group A streptococcus (GAS)
such as type 12 and type 49. The clinical presentation can vary from asymptomatic, microscopic
hematuria to full-blown acute nephritic syndrome, characterized by red to brown urine, proteinuria
(which can reach the nephrotic range), edema, hypertension and acute renal failure.
A latent period always occurs between the streptococcal infection and the onset of signs and
symptoms of acute glomerulonephritis. In general, the latent period is 1-2 weeks after a throat
infection and 3-6 weeks after a skin infection. The onset of signs and symptoms at the same time
as pharyngitis is points towards immunoglobulin A (IgA) nephropathy rather than PSGN.
Dark urine (brown-, tea-, or cola-colored) is often the first clinical manifestation of PSGN. Dark urine
is caused by lysis of red blood cells that have penetrated the glomerular basement membrane and
have passed into the tubular system.
Periorbital edema is typical. The onset of puffiness of the face or eyelids is sudden. It is usually
prominent upon waking up and, if the patient is active, tends to subside toward the end of the day.
In some cases, generalized edema and other features of circulatory congestion, such as dyspnea,
may be present. Edema is the result of a defect in renal excretion of salt and water. The severity of
edema is often disproportionate to the degree of renal impairment. Nonspecific symptoms of
PSGN can include general malaise, weakness, and anorexia that are present in 50% of patients.
Approximately 15% of patients complain of nausea and vomiting.
Early death is extremely rare in children (<1%) but is significantly more common in adults (25%).
This is secondary to congestive heart failure and azotemia. Left ventricular failure (congestive
heart failure) is more common in adults (43%) than in children (<5%); therefore, this patient is
potentially at immediate risk of congestive heart failure and death due to volume overload.
RENAL/UROLOGY','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-ebf3bd534110","duplicate_sources":[{"record_id":"622ba69e065c96096013","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1869,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"622ba69e065c96096013","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1869,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 35-year-old man with history of sore throat three weeks ago, presents to the Emergency\nDepartment with a puffy face and decreased urine output for the past 48 hours. On examination, he\nhas a blood pressure of 160/120 mmHg. His face is swollen especially in the periorbital area. On\nlung auscultation, bilbasal crepitations are heard. Which one of the following is correct regarding\nhis condition?","options":{"A":"Hematuria is a grave prognostic factor.","B":"He is at immediate risk of death from left ventricular failure.","C":"Increase in oral intake will result in diuresis.","D":"If there is renal tenderness, a renal biopsy should be performed.","E":"Dialysis is contraindicated during the acute phase of the illness."},"source_answer":"B","source_explanation":"Facial edema, hypertension and oliguria are strong pointers towards glomerulonephritis. With the\nsore throat in the history, post-streptococcal glomerulonephritis (PSGN) is the most likely cause of\nthis presentation.\nPSGN is induced by infection with specific nephritogenic strains of group A streptococcus (GAS)\nsuch as type 12 and type 49. The clinical presentation can vary from asymptomatic, microscopic\nhematuria to full-blown acute nephritic syndrome, characterized by red to brown urine, proteinuria\n(which can reach the nephrotic range), edema, hypertension and acute renal failure.\nA latent period always occurs between the streptococcal infection and the onset of signs and\nsymptoms of acute glomerulonephritis. In general, the latent period is 1-2 weeks after a throat\ninfection and 3-6 weeks after a skin infection. The onset of signs and symptoms at the same time\nas pharyngitis is points towards immunoglobulin A (IgA) nephropathy rather than PSGN.\nDark urine (brown-, tea-, or cola-colored) is often the first clinical manifestation of PSGN. Dark urine\nis caused by lysis of red blood cells that have penetrated the glomerular basement membrane and\nhave passed into the tubular system.\nPeriorbital edema is typical. The onset of puffiness of the face or eyelids is sudden. It is usually\nprominent upon waking up and, if the patient is active, tends to subside toward the end of the day.\nIn some cases, generalized edema and other features of circulatory congestion, such as dyspnea,\nmay be present. Edema is the result of a defect in renal excretion of salt and water. The severity of\nedema is often disproportionate to the degree of renal impairment. Nonspecific symptoms of\nPSGN can include general malaise, weakness, and anorexia that are present in 50% of patients.\nApproximately 15% of patients complain of nausea and vomiting.\nEarly death is extremely rare in children (<1%) but is significantly more common in adults (25%).\nThis is secondary to congestive heart failure and azotemia. Left ventricular failure (congestive\nheart failure) is more common in adults (43%) than in children (<5%); therefore, this patient is\npotentially at immediate risk of congestive heart failure and death due to volume overload.\nRENAL/UROLOGY","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["hypertension"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"ebf3bd534110339e6189de1d9ceffd18b62f29b2","duplicate_group_id":"exact-ebf3bd534110","duplicate_sources":[{"record_id":"622ba69e065c96096013","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1869,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
