INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('66a7a644cecd38617c1a','Amedex 2023.pdf','1871','Mixed/Unclassified','A 72-year-old man presents with complaint of one episode or blood in the urine. Five years ago, he
underwent colectomy after he was diagnosed with colon cancer. A while back, he developed back
pain for which he was assessed and diagnosed with metastatic bone disease. Three months ago
he was started on tramadol for management of the back pain. He has no urinary symptoms. Which
one of the following is the most appropriate next best step in management?','{"A":"Perform a pelvic and abdominal CT scan.","B":"Perform a renal ultrasound.","C":"Urine culture.","D":"Stop tramadol.","E":"Perform an intravenous pyelogram (IVP)."}','C','Hematuria should be always considered as a sign; therefore, for established cases of hematuria an
underlying cause should be investigated through history, physical examinations and
laboratory/imaging studies. For established hematuria, the most common causes such as vigorous
exercise, menstruation, trauma, viral illnesses, and infections should be excluded first.
One of the most common causes of hematuria even in the absence of symptoms is urinary tract
infection (UTI), for which a urine analysis and culture should be performed.
(Option A) Genitourinary malignancies (either primary or metastatic) can cause hematuria.
Malignancies should always be excluded and CT scan is one of the most accurate and commonly
used means. However, other common causes of hematuria should be excluded first.
(Option B) Renal ultrasound may be later needed as further work-up but not as the first priority
because the hematuria has been painless, making renal stones less likely. Small stones may cause
painless hematuria, but since they almost always pass spontaneously, their detection on
sonography does not change the management plan.
(Option D) Although hematuria has been reported as a rather rare adverse effect of tramadol, initial
assessment should be focused on more common possibilities such as UTI. Even so, cessation of
tramadol in an almost end-stage patient would not be recommended.
(Option E) If imaging studies are required during the evaluation process, CT scan is preferred over
IVP. In the presence of more modern and convenient modalities, IVP is rarely done these days.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-7df9b94bde67","duplicate_sources":[{"record_id":"66a7a644cecd38617c1a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1871,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"66a7a644cecd38617c1a","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1871,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 72-year-old man presents with complaint of one episode or blood in the urine. Five years ago, he\nunderwent colectomy after he was diagnosed with colon cancer. A while back, he developed back\npain for which he was assessed and diagnosed with metastatic bone disease. Three months ago\nhe was started on tramadol for management of the back pain. He has no urinary symptoms. Which\none of the following is the most appropriate next best step in management?","options":{"A":"Perform a pelvic and abdominal CT scan.","B":"Perform a renal ultrasound.","C":"Urine culture.","D":"Stop tramadol.","E":"Perform an intravenous pyelogram (IVP)."},"source_answer":"C","source_explanation":"Hematuria should be always considered as a sign; therefore, for established cases of hematuria an\nunderlying cause should be investigated through history, physical examinations and\nlaboratory/imaging studies. For established hematuria, the most common causes such as vigorous\nexercise, menstruation, trauma, viral illnesses, and infections should be excluded first.\nOne