INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4cdbcaa04f56cdb6c3d2','Amedex 2023.pdf','1873','Mixed/Unclassified','A 65-year-old man presents to your practice with complaint of blood in the urine. These episodes of
hematuria have all been painless. Which one of the following is the least likely cause of painless
hematuria?','{"A":"Cancer within the kidney.","B":"Anticoagulantion therapy.","C":"Glomerulonephritis.","D":"Benign prostatic hyperplasia (BPH).","E":"Use of cyclophosphamide."}','E','All the given options can present with painless hematuria except cyclophosphamide.
Cyclophosphamide use can result in hemorrhagic cystitis. With cystitis, the hematuria is more likely
to be painful rather than painless.
The following can result in hematuria (painless or painful):
Urothelial cancers (kidney cancers, bladder cancers, etc)
Hydronephrosis/distention
Renal vein thrombus / renal artery embolism
Arteriorvenous malformation
Papillary necrosis (sickle cell disease)
Hypertension
Glomerulonephritis
Structural abnormalities (polycystic kidney disease, medullary sponge kidney, etc)
Nephrolithiasis
Urinary tract infections (pyelonephritis, cystitis, parasitic infections, etc)
Ureteral strictures
BPH
Prostate cancer
Prostatic procedures
Trauma (including traumatic catheterization)
Exercise-induced hematuria
Bleeding diathesis / anticoagulation
Urethritis
Urethral diverticulum
Hypercalciuria/hyperuricosuria
Urinary tract fistulas
Mimics of hematuria:
Menstruation
Drugs (phenazopyridine, pyriduim, rifampin, nitrofurantoin, etc)','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-dfca8a432ed1","duplicate_sources":[{"record_id":"4cdbcaa04f56cdb6c3d2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1873,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"4cdbcaa04f56cdb6c3d2","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1873,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 65-year-old man presents to your practice with complaint of blood in the urine. These episodes of\nhematuria have all been painless. Which one of the following is the least likely cause of painless\nhematuria?","options":{"A":"Cancer within the kidney.","B":"Anticoagulantion therapy.","C":"Glomerulonephritis.","D":"Benign prostatic hyperplasia (BPH).","E":"Use of cyclophosphamide."},"source_answer":"E","source_explanation":"All the given options can present with painless hematuria except cyclophosphamide.\nCyclophosphamide use can result in hemorrhagic cystitis. With cystitis, the hematuria is more likely\nto be painful rather than painless.\nThe following can result in hematuria (painless or painful):\nUrothelial cancers (kidney cancers, bladder cancers, etc)\nHydronephrosis/distention\nRenal vein thrombus / renal artery embolism\nArteriorvenous malformation\nPapillary necrosis (sickle cell disease)\nHypertension\nGlomerulonephritis\nStructural abnormalities (polycystic kidney disease, medullary sponge kidney, etc)\nNephrolithiasis\nUrinary tract infections (pyelone