INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1850e0ae205f2ddb9fd6','Amedex 2023.pdf','1875','Mixed/Unclassified','A couple has presented to your office for infertility consult. They have been trying to start a family
for over a year. The woman’s history and examination results are normal, but the man is found to
have absent vas deferens. Which one of the following would be the most appropriate advice for
them?','{"A":"They should have sperm donation.","B":"The vas deferens should be fused to the ejaculatory duct.","C":"Sperm aspiration and intrauterine fertilization should be tried.","D":"Sperm aspiration for frozen sample and repeated tubal insemination.","E":"In vitro fertilization."}','E','One to two percent of infertile men have congenital absence of the vas deferens. Most have
mutations of the cystic fibrosis transmembrane conductance regulator (CFTR) gene. Many infertile
men with mutations of CFTR present with infertility in the absence of other typical features of
cystic fibrosis (e.g. respiratory and pancreatic disease).
Using in vitro fertilisation is the most appropriate reproductive technique for this couple. Sperms
are aspirated from epididymis or testis and then injected into the aspirated oocytes in vitro.
NOTE - Patients with congenital bilateral absence of the vas deferens may have genetic mutation
commonly present in cystic fibrosis. Such men and their partners who are considering assisted
reproductive techniques to achieve pregnancy should have genetic screening and counselling.
Screening the female partner may be more cost effective than screening the patient because if she
is negative, the risk that their children having cystic fibrosis is almost zero. 
(Option A) Sperm donation, while the male sperms are retrievable, is not an appropriate treatment
option.
(Option B) Fusion of vas deferens to ejaculatory duct is considered appropriate for male patients,
who have vas deferens but has undergone vasectomy.
(Options C and D) Aspirated sperms are not enough in number to make intrauterine infertilization
or tubal insemination acceptable methods.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"897","duplicate_group_id":"exact-e9c433ac6671","duplicate_sources":[{"record_id":"1850e0ae205f2ddb9fd6","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1875,"source_qid":"897"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"1850e0ae205f2ddb9fd6","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1875,"source_qid":"897","domain_hint":"Mixed/Unclassified","stem":"A couple has presented to your office for infertility consult. They have been trying to start a family\nfor over a year. The woman’s history and examination results are normal, but the man is found to\nhave absent vas deferens. Which one of the following would be the most appropriate advice for\nthem?","options":{"A":"They should have sperm donation.","B":"The vas deferens should be fused to the ejaculatory duct.","C":"Sperm aspiration and intrauterine fertilization should be tried.","D":"Sperm aspiration for frozen sample and repeated tubal insemination.","E":"In vitro fertilization."},"source_answer":"E","source_explanation":"One to two percent of infertile men have congenital absence of the vas deferens. Most have\nmutations of the cystic fibrosis transmembrane conductance regulator (CFTR) gene. Many infertile\nmen with mutations of CFTR present with infertility in the absence of other typical features of\ncystic fibrosis (e.g. respiratory and pancreatic disease).\nUsing in vitro fertilisation is the most appropriate reproductive technique for this couple. Sperms\nare aspirated from epididymis or testis and then injected into the aspirated oocytes in vitro.\nNOTE - Patients with congenital bilateral absence of the vas deferens may have genetic mutation\ncommonly present in cystic fibrosis. Such men and their partners who are considering assisted\nreproductive techniques to achieve pregnancy should have genetic screening and counselling.\nScreening the female partner may be more cost effective than screening the patient because if she\nis negative, the risk that their children having cystic fibrosis is almost zero. \n(Option A) Sperm donation, while the male sperms are retrievable, is not an appropriate treatment\noption.\n(Option B) Fusion of vas deferens to ejaculatory duct is considered appropriate for male patients,\nwho have vas deferens but has undergone vasectomy.\n(Options C and D) Aspirated sperms are not enough in number to make intrauterine infertilization\nor tubal insemination acceptable methods.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["pregnan","screen","screening","treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"e9c433ac667191fd48e9abb0e3a0f336e63aa677","duplicate_group_id":"exact-e9c433ac6671","duplicate_sources":[{"record_id":"1850e0ae205f2ddb9fd6","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1875,"source_qid":"897"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=exclud