INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('2b0f4f8a125b33c3a0c5','Amedex 2023.pdf','1876','Mixed/Unclassified','A 65-year-old man, who is on chronic hemodialysis every other day due to chronic renal failure,
presents to the Emergency Department with generalized weakness and dyspnea. He is non-
compliant with his dialysis sessions and had his last session 5 days ago. Which one of the
following would be the most appropriate next action to take?','{"A":"Call the dialysis unit.","B":"Arterial blood gas (ABG) analysis.","C":"ECG.","D":"Chest X-ray (CXR).","E":"Furosemide."}','A','This patient has skipped dialysis sessions. Patients with end stage renal disease have volume
overload and hazardous metabolic derangements such as metabolic acidosis and hyperkalemia,
both of which can be fatal. Volume overload can cause congestive heart failure and pulmonary
edema presenting with dyspnea as the most common manifestation. Hyperkalemia is also of great
concern because it can cause lethal cardiac arrhythmias. No matter what the underlying cause
of this presentation is, arrangement for urgent dialysis is the most appropriate next step in
management as it shoud be arranged at earliest time. While the arrangements are in process,
investigations such as ECG (option C), CXR (option D) and ABG (option B) can be undertaken. ECG
is of paramount importance because with evidence of arrhythmias induced by hyperkalemia,
calcium gluconate should be administered promptly for cardiac protection.
Urgent dialysis can remove excess fluid and the congestion; in the mean time, standard protocols
should be used for such patients. In case of pulmonary edema, furosemide (option E) can be used
in patients with preserved renal function as a component of acute management of pulmonary
edema.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"917","duplicate_group_id":"exact-2eaa0364d897","duplicate_sources":[{"record_id":"2b0f4f8a125b33c3a0c5","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1876,"source_qid":"917"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"2b0f4f8a125b33c3a0c5","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1876,"source_qid":"917","domain_hint":"Mixed/Unclassified","stem":"A 65-year-old man, who is on chronic hemodialysis every other day due to chronic renal failure,\npresents to the Emergency Department with generalized weakness and dyspnea. He is non-\ncompliant with his dialysis sessions and had his last session 5 days ago. Which one of the\nfollowing would be the most appropriate next action to take?","options":{"A":"Call the dialysis unit.","B":"Arterial blood gas (ABG) analysis.","C":"ECG.","D":"Chest X-ray (CXR).","E":"Furosemide."},"source_answer":"A","source_explanation":"This patient has skipped dialysis sessions. Patients with end stage renal disease have volume\noverload and hazardous metabolic derangements such as metabolic acidosis and hyperkalemia,\nboth of which can be fatal. Volume overload can cause congestive heart failure and pulmonary\nedema presenting with dyspnea as the most common manifestation. Hyperkalemia is also of great\nconcern because it can cause lethal cardiac arrhythmias. No matter what the underlying cause\nof this presentation is, arrangement for urgent dialysis is the most appropriate next step in\nmanagement as it shoud be arranged at earliest time. While the arrangements are in process,\ninvestigations such as ECG (option C), CXR (option D) and ABG (option B) can be undertaken. ECG\nis of paramount importance because with evidence of arrhythmias induced by hyperkalemia,\ncalcium gluconate should be administered promptly for cardiac protection.\nUrgent dialysis can remove excess fluid and the congestion; in the mean time, standard protocols\nshould be used for such patients. In case of pulmonary edema, furosemide (option E) can be used\nin patients with preserved renal function as a component of acute management of pulmonary\nedema.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":true,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"2eaa0364d8976bba6d7f8d77433076f1cbd74482","duplicate_group_id":"exact-2eaa0364d897","duplicate_sources":[{"record_id":"2b0f4f8a125b33c3a0c5","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1876,"source_qid":"917"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_qui