INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ad82275b80ce2120a866','Amedex 2023.pdf','1877','Mixed/Unclassified','A 70-year-old woman presents with increasing generalized abdominal pain for the past 2 hours.
She is a known case of chronic renal failure and has been on peritoneal dialysis for the past 18
months. Her last dialysis session was hours ago. On examination, she appears toxic. Her blood
pressure is 140/95mmHg, heart rate 110bpm, and temperature 39°C. Her abdomen is distended
and diffusely tender to deep palpation. Rebound tenderness is also noted. Blood exam is
significant for a white cell count of 18,000/mm3. Which one of the following is the most
appropriate next step in management?','{"A":"Erect and supine abdominal films.","B":"Ultrasonography of the abdomen.","C":"CT scan of the abdomen and pelvis.","D":"Peritoneal fluid analysis and Gram stain.","E":"Comparison of ascitic fluid amylase with serum amylase."}','D','In the setting of peritoneal dialysis (PD), peritonitis is the most likely explanation to this
presentation.
Peritonitis is a common complication of peritoneal dialysis (PD), and is associated with significant
morbidity, catheter loss, transfer to hemodialysis, transient loss of ultrafiltration, possible
permanent membrane damage, and occasionally death.
Among PD patients, peritonitis may be PD-related or secondary (enteric). PD-related peritonitis is
due to touch contamination with pathogenic skin bacteria or to catheter-related infection.
Secondary peritonitis is caused by underlying pathology of the gastrointestinal tract. PD-related
peritonitis is much more common than secondary peritonitis; the latter, however, is associated with
higher rates of complications and mortality. Conditions that may lead to secondary peritonitis
include cholecystitis, appendicitis, ruptured diverticulum, treatment of severe constipation,
perforation during endoscopy, bowel ischemia, and incarcerated hernia.Secondary peritonitis may
also be caused by seeding from the blood or vagina but this is less common compared to intra-
abdominal causes.
The most common signs and symptoms of peritonitis among PD patients are abdominal pain and
cloudy peritoneal effluent. Other signs and symptoms include fever, nausea, diarrhea, abdominal
tenderness, rebound tenderness, and occasionally systemic signs, including hypotension.
The diagnosis of peritonitis should be suspected in a PD patient with characteristic clinical
presentation. Analysis of the peritoneal fluid is the most appropriate next step when PD-related
peritonitis is suspects.
A presumptive diagnosis is made if the peritoneal fluid white cell count is greater than 100
cells/mm3 and the percentage of neutrophils is greater than 50%. The white cell count is greatly
dependent on the dwell time of the dialysis catheter; therefore, with a white cell count of less than','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-2e2d5fdb55e4","duplicate_sources":[{"record_id":"ad82275b80ce2120a866","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1877,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"ad82275b80ce2120a866","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1877,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 70-year-old woman presents with increasing generalized abdominal pain for the past 2 hours.\nShe is a known case of chronic renal failure and has been on peritoneal dialysis for the past 18\nmonths. Her last dialysis session was hours ago. On examination, she appears toxic. Her blood\npressure is 140/95mmHg, heart rate 110bpm, and temperature 39°C. Her abdomen is distended\nand diffusely tender to deep palpation. Rebound tenderness is also noted. Blood exam is\nsignificant for a white cell count of 18,000/mm3. Which one of the following is the most\nappropriate next step in management?","options":{"A":"Erect and supine abdominal films.","B":"Ultrasonography of the abdomen.","C":"CT scan of the abdomen and pelvis.","D":"Peritoneal fluid analysis and Gram stain.","E":"Comparison of ascitic fluid amylase with serum amylase."},"source_answer":"D","source_explanation":"In the setting of peritoneal dialysis (PD), peritonitis is the most likely explanation to this\npresentation.\nPeritonitis is a common complication of peritoneal dialysi