INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a317bebbaf974d57e520','Amedex 2023.pdf','1879','Mixed/Unclassified','A 60-year-old man with end-stage renal failure presents to the dialysis unit for a session of
hemodialysis. His current medications are enalapril, hydrochlorothiazide, and aspirin. He has a
blood pressure of 140/95 mmHg. After the session, which was uneventful, his blood pressure is
found to be 160/90mmHg. Which one of the following is more likely to be the cause of his
increased blood pressure?','{"A":"Allergic reaction to the dialysis fluid.","B":"Overdialysis.","C":"Enalapril overdose.","D":"Hypokalemia.","E":"Anemia."}','B','While hemodialysis lowers blood pressure (BP) in most hypertensive end-stage renal disease
patients, approximately 15% of patients show a paradoxical increase in BP during haemodialysis,
termed intradialytic hypertension (IDH). IDH is defined as either of the following:
An increase in mean arterial blood pressure (MAP) ≥ 15 mmHg during or immediately after
hemodialysis
An increase in systolic BP (SBP) >10 mmHg from pre- to post-dialysis
Hypertension during the second or third hour of hemodialysis after significant ultrafiltration
has taken place
An increase in BP that is resistant to ultrafiltration
Aggravation of pre-existing hypertension or development of de novo hypertension with
erythropoietin stimulating agents.
Despite extensive investigations as to the mechanism and pathophysiology of IDH, the exact
pathogenesis remains unclear. Numerous factors have been implicated, including:
1. Renin-angiotensin system activation because of ultrafiltration (UF) induced hypovolemia
2. Sympathetic overactivity
3. Intradialytic Ca++/k+ variations
4. Blood viscosity/haemoconcentration-induced vasoconstriction caused by erythropoietin
treatment
5. Fluid overload
6. Increased cardiac output
7. Endothelin-driven vasoconstriction
8. Antihypertensive drug removal by dialysis treatment
Several studies and reports highlight the important role of fluid overload, hemodynamic changes
and increased endothelin level. The importance of other hypothesis such as renin-angiotensin
system activation, sympathetic overactivity and ionic variations seems secondary. Fluid removal
remains the key point for treatment of IDH.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-c9ce9ead0ad8","duplicate_sources":[{"record_id":"a317bebbaf974d57e520","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1879,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"a317bebbaf974d57e520","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1879,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 60-year-old man with end-stage renal failure presents to the dialysis unit for a session of\nhemodialysis. His current medications are enalapril, hydrochlorothiazide, and aspirin. He has a\nblood pressure of 140/95 mmHg. After the session, which was uneventful, his blood pressure is\nfound to be 160/90mmHg. Which one of the following is more likely to be the cause of his\nincreased blood pressure?","options":{"A":"Allergic reaction to the dialysis fluid.","B":"Overdialysis.","C":"Enalapril overdose.","D":"Hypokalemia.","E":"Anemia."},"source_answer":"B","source_explanation":"While hemodialysis lowers blood pressure (BP) in most hypertensive end-stage renal disease\npatients, approximately 15% of patients show a paradoxical increase in BP during haemodialysis,\ntermed intradialytic hypertension (IDH). IDH is defined as either of the following:\nAn increase in mean arterial blood pressure (MAP) ≥ 15 mmHg during or immediately after\nhemodialysis\nAn increase in systolic BP (SBP) >10 mmHg from pre- to post-dialysis\nHypertension during the second or third hour of hemodialysis after significant ultrafiltration\nhas taken place\nAn increase in BP that is resistant to ultrafiltration\nAggravation of pre-existing hypertension or development of de novo hypertension with\nerythropoietin stimulating agents.\nDespite extensive investigations as to the mechanism and pathophysiology of IDH, the exact\npathogenesis remains unclear. Numerous factors have been implicated, including:\n1. Renin-angiotensin system activation because of ultrafiltration (UF) induced hypovolemia\n2. Sympathetic overactivity\n3. Intradialytic Ca++/k+ variations\n4. Blood viscosity/haemoconcentration-induced vasoconstriction caused by erythropoietin\ntreatment\n5. Fluid overload\n6. Increased cardiac output\n7. Endothelin-driven vasoconstriction\n8. Antihypertensive drug removal by dialysis treatment\nSeveral studies and reports highlight the important role of fluid overload, hemodynamic changes\nand increased endothelin level. The importance of other hypothesis such as renin-angiotensin\nsystem activation, sympathetic overactivity and ionic variations seems secondary. Fluid removal\nremains the key point for treatment of IDH.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","drug","hypertension","treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"c9ce9ead0ad8aaf7ad7fce7da1c180c33103de22","duplicate_group_id":"exact-c9ce9ead0ad8","duplicate_sources":[{"record_id":"a317bebbaf974d57e520","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1879,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=exclu