INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('05cf5c19715548a98059','Amedex 2023.pdf','1881','Mixed/Unclassified','A 64-year-old man with end-stage renal disease presents to the dialysis unit for a pre-scheduled
hemodialysis session. He proceeds through the session uneventfully, but his blood pressure
reading is 80/60 mmHg at the end of the session. His pre-dialysis blood pressure was 150/90
mmHg. A blood panel shows a hemoglobin level of 80 g/L. Which one of the following could be the
most likely cause of this drop in blood pressure?','{"A":"Allergic reaction to the dialysis fluid.","B":"Overdialysis.","C":"Anemia.","D":"Hypokalemia.","E":"Enalapril overdose."}','B','The scenario is a typical example of intradialytic hypotension. Intra- or post-dialysis hypotension is
a well recognized and common complication of hemodialysis.
The incidence of a symptomatic reduction in blood pressure during (or immediately following)
dialysis ranges from 15-50% of dialysis sessions. In some patients, the development of orthostatic
hypotension necessitates intravenous fluid replacement before they are able to leave the dialysis
unit. This problem contributes to the excessive morbidity associated with the dialysis procedure.
There are two clinical patterns of dialysis-associated hypotension:
Episodic hypotension, which typically occurs during the later stages of dialysis and presents
with vomiting, muscle cramps, and other vagal symptoms (such as yawning)
Chronic persistent hypotension, which may occur in patients with long-term dialysis. A pre-
dialysis systolic blood pressures of less than 100 mmHg is frequently observed
The etiology of intradialytic hypotension is divers and includes:
A rapid reduction in plasma osmolality, which causes extracellular water to move into the
cells
Rapid fluid removal in an attempt to attain "dry weight", particularly among those with large
inter-dialytic weight gains
Inaccurate determination of true ‘dry weight’
Autonomic neuropathy
Diminished cardiac reserve
Use of acetate rather than bicarbonate as a dialysate buffer
Intake of antihypertensive medications that can impair cardiovascular stability
Use of a lower sodium concentration in the dialysate
Sudden release of adenosine during organ ischemia
Ingestion of a meal immediately before or during dialysis','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-9c7803fbee26","duplicate_sources":[{"record_id":"05cf5c19715548a98059","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1881,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"05cf5c19715548a98059","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1881,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 64-year-old man with end-stage renal disease presents to the dialysis unit for a pre-scheduled\nhemodialysis session. He proceeds through the session uneventfully, but his blood pressure\nreading is 80/60 mmHg at the end of the session. His pre-dialysis blood pressure was 150/90\nmmHg. A blood panel shows a hemoglobin level of 80 g/L. Which one of the following could be the\nmost likely cause of this drop in blood pressure?","options":{"A":"Allergic reaction to the dialysis fluid.","B":"Overdialysis.","C":"Anemia.","D":"Hypokalemia.","E":"Enalapril overdose."},"source_answer":"B","source_explanation":"The scenario is a typical example of intradialytic hypotension. Intra- or post-dialysis hypotension is\na well recognized and common complication of hemodialysis.\nThe incidence of a symptomatic reduction in blood pressure during (or immediately following)\ndialysis ranges from 15-50% of dialysis sessions. In some patients, the development of orthostatic\nhypotension necessitates intravenous fluid replacement before they are able to leave the dialysis\nunit. This problem con