INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9a29ae7d8fe591fc409c','Amedex 2023.pdf','1883','Mixed/Unclassified','A 72-year-old woman has been on routine dialysis sessions for the past 6 months due to end-stage
renal disease. At the beginning of each session, she is found to have a high blood pressure (BP).
During the session the BP normalizes, but goes up again after the session. Which one of the
following would be the most appropriate management option for this patient?','{"A":"Addition of hypertensive medications.","B":"Addition of furosemide, daily.","C":"Increasing the dialysis time.","D":"Sedation before dialysis.","E":"Decreasing the dialysis time."}','C','Although hypotension during hemodialysis is a frequent complication, some patients (5-15%)
develop paradoxical hypertension in the later stages of dialysis or when the patients comes off the
dialysis machine, a time at which most of the excess fluid has already been removed. The
pathogenesis is unclear; however, the following mechanisms have been hypothesized as the cause:
1. Renin-angiotensin system activation because of ultrafiltration (UF) induced hypovolemia
2. Sympathetic overactivity
3. Intradialytic Ca++/k+ variations
4. Blood viscosity/hemoconcentration-induced vasoconstriction caused by erythropoietin
treatment
5. Fluid overload
6. Increased cardiac output
7. Endothelin-driven vasoconstriction
8. Antihypertensive drug removal by dialysis treatment
The optimal therapy for this problem is not known. While antihypertensive medications such as
angiotensin converting enzyme inhibitors (ACE inhibitors) and alpha-blockers have been used
before (or during) dialysis, they have not been predictably effective. Carvedilol, which blocks
endothelin-1 release, appears to be effective.
Although there are no validated universal guidelines regarding management of such patients, fluid
removal has been accepted as the first-line treatment for intradialytic hypertension (IDH).
Theoretically, increasing the time of the dialysis session and ultrafiltration (UF) rate would be
efficient; however, this decision faces many difficulties such as patient refusal or the unit
limitations. This treatment should be done with caution to avoid hazardous blood pressure drop
that may occur in the elderly or patients with severe comorbidity.
The dry weight of patients should be gradually reduced by increasing the dialysis time and the UF
rate. In addition, patients should be advised to decrease their daily salt and water intake in
between their dialysis sessions.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-8d591e507bdb","duplicate_sources":[{"record_id":"9a29ae7d8fe591fc409c","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1883,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"9a29ae7d8fe591fc409c","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1883,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 72-year-old woman has been on routine dialysis sessions for the past 6 months due to end-stage\nrenal disease. At the beginning of each session, she is found to have a high blood pressure (BP).\nDuring the session the BP normalizes, but goes up again after the session. Which one of the\nfollowing would be the most appropriate management option for this patient?","options":{"A":"Addition of hypertensive medications.","B":"Addition of furosemide, daily.","C":"Increasing the dialysis time.","D":"Sedation before dialysis.","E":"Decreasing the dialysis time."},"source_answer":"C","source_explanation":"Although hypotension during hemodialysis is a frequent complication, some patients (5-15%)\ndevelop paradoxical hypertension in the later stages of dialysis or when the patients comes off the\ndialysis machine, a time at which most of the excess fluid has already been removed. The\npathogenesis is unclear; however, the following mechanisms have been hypothesized as the cause:\n1. Renin-angiotensin system activation because of ultrafiltration (UF) induced hypovolemia\n2. Sympathetic overactivity\n3. Intradialytic Ca++/k+ variations\n4. Blood viscosity/hemoconcentration-induced vasoconstriction caused by erythropoietin\ntreatment\n5. Fluid overload\n6. Increased cardiac output\n7. Endothelin-driven vasoconstriction\n8. Antihypertensive drug removal by dialysis treatment\nThe optimal therapy for this problem is not known. While antihypertensive medications such as\nangiotensin converting enzyme inhibitors (ACE inhibitors) and alpha-blockers have been used\nbefore (or during) dialysis, they have not been predictably effective. Carvedilol, which blocks\nendothelin-1 release, appears to be effective.\nAlthough there are no validated universal guidelines regarding management of such patients, fluid\nremoval has been accepted as the first-line treatment for intradialytic hypertension (IDH).\nTheoretically, increasing the time of the dialysis session and ultrafiltration (UF) rate would be\nefficient; however, this decision faces many difficulties such as patient refusal or the unit\nlimitations. This treatment should be done with caution to avoid hazardous blood pressure drop\nthat may occur in the elderly or patients with severe comorbidity.\nThe dry weight of patients should be gradually reduced by increasing the dialysis time and the UF\nrate. In addition, patients should be advised to decrease their daily salt and water intake in\nbetween their dialysis sessions.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","drug","guideline","hypertension","management","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"8d591e507bdbce837b9dbac147b2084e9f03da62","duplicate_group_id":"exact-8d591e507bdb","duplicate_sources":[{"record_id":"9a29ae7d8fe591fc409c","record_type":"text_mcq","sourc