INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('c8e3ec90df9ae3127ca4','Amedex 2023.pdf','1887','Mixed/Unclassified','A 32-year-old man presents to the Emergency Deaprtment with left loin pain and hematuria. He is
HIV positive and on an anti-HIV treatment regimen including indinavir. This is the first time he is
having sych problem. Urine dipstick is positive for blood but negative for urinary tract infection.
Which one of the following is the most appropriate next step in management?','{"A":"Intravenous pyelogram (IVP).","B":"Ultrasound (US).","C":"Non-contrast CT scan.","D":"KUB X-ray.","E":"Triple-phase CT scan."}','B','Indinavir sulfate is an HIV protease inhibitor. Indinavir-induced nephrolithiasis is a well-recognized
adverse effect of this drug, occurring in almost 12.4% of patients. If indinavir-induced
nephrolithiasis develops, the drug should be discontinued and an alternative antiretroviral be used.
Non-contrast helical CT scan (option C) is the criterion standard for evaluation of nephrolithiasis.
This modality can detect both stones and urinary tract obstruction. Stones not visualized on IVP or
KUB, usually are detected on CT scan; however, since stones secondary to indinavir are not
radiopaque and signs of obstruction may be minimal, this modality may not be as accurate and
miss the diagnosis. This holds true about x-ray KUB (option D) and ultrasound.
Although not accurate as non-contrast helical CT scan, ultrasound can detect obstruction caused
by large, clinically significant stones and probably the stone itself. This modality has been
recommended as the initial diagnostic option by many authors. It is safe, readily available, cost-
effective, and spares patients from the risk of radiation in most cases. Again, the accuracy is
reduced in detection of stones secondary to indinavir.
In fact, studies have shown that contrast CT-scan is more likely to visualize indinavir-induced
stones, but since most of such stones, especially if not large enough to cause obstruction and be
detected on ultrasonography, will pass with conservative management, contrast enhanced imaging
studies as contrast CT or IVP (option A) unnecessarily puts the patient at risk of radiation and/or
contrast media.
Contrast CT scan, however, should be considered for patients in whom the symptoms persist or
other diagnosis is suspected based on clinical grounds.
Triple phase CT scan (option E) is mostly used for diagnosis of liver lesions. It is not indicated
diagnosis of renal stones but may be considered if an alternative diagnosis','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-ecd3af0e061e","duplicate_sources":[{"record_id":"c8e3ec90df9ae3127ca4","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1887,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"c8e3ec90df9ae3127ca4","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1887,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 32-year-old man presents to the Emergency Deaprtment with left loin pain and hematuria. He is\nHIV positive and on an anti-HIV treatment regimen including indinavir. This is the first time he is\nhaving sych problem. Urine dipstick is positive for blood but negative for urinary tract infection.\nWhich one of the following is the most appropriate next step in management?","options":{"A":"Intravenous pyelogram (IVP).","B":"Ultrasound (US).","C":"Non-contrast CT scan.","D":"KUB X-ray.","E":"Triple-phase CT scan."},"source_answer":"B","source_explanation":"Indinavir sulfate is an HIV protease inhibitor. Indinavir-induced nephrolithiasis is a well-recognized\nadverse effect of this drug, occurring in almost 12.4% of patients. If indinavir-induced\nnephrolithiasis develops, the drug should be discontinued and an alternative antiretroviral be used.\nNon-contrast helical CT scan (option C) is the criterion standard for evaluation of nephrolithiasis.\nThis modality can detect both stones and urinary tract obstruction. Stones not visualized on IVP or\nKUB, usually are detected on CT scan; however, since stones secondary to indinavir are not\nradiopaque and signs of obstruction may be minimal, this modality may not be as accurate and\nmiss the diagnosis. This holds true about x-ray KUB (option D) and ultrasound.\nAlthough not accurate as non-contrast helical CT scan, ultrasound can detect obstruction caused\nby large, clinically significant stones and probably the stone itself. This modality has been\nrecommended as the initial diagnostic option by many authors. It is safe, readily available, cost-\neffective, and spares patients from the risk of radiation in most cases. Again, the accuracy is\nreduced in detection of stones secondary to indinavir.\nIn fact, studies have shown that contrast CT-scan is more likely to visualize indinavir-induced\nstones, but since most of such stones, especially if not large enough to cause obstruction and be\ndetected on ultrasonography, will pass with conservative management, contrast enhanced imaging\nstudies as contrast CT or IVP (option A) unnecessarily puts the patient at risk of radiation and/or\ncontrast media.\nContrast CT scan, however, should be considered for patients in whom the symptoms persist or\nother diagnosis is suspected based on clinical grounds.\nTriple phase CT scan (option E) is mostly used for diagnosis of liver lesions. It is not indicated\ndiagnosis of renal stones but may be considered if an alternative diagnosis","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","drug","management","treatment"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"ecd3af0e061e4b6c966ec8efb0838a9f50a7712e","duplicate_group_id":"exact-ecd3af0e061e","duplicate_sources":[{"record_id":"c8e3ec90df9ae3127ca4","record_type":"