INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ad4788fe2880d60b835b','Amedex 2023.pdf','1889','Mixed/Unclassified','During a routine health assessment, a 43-year-old man is found to have established asymptomatic
hematuria. Which one of the following is the most appropriate next step in management?','{"A":"Ultrasonography of the renal system.","B":"CT scan.","C":"Cystoscopy.","D":"Urine culture.","E":"Intravenous pyelogram (IVP)."}','D','Hematuria may be seen in a variety of situations including, but not limited to:
Infections
Renal stones
Glomerulonephritis
Urinary tract malignancies
Trauma
Infections are the most common cause of hematuria in both symptomatic and asymptomatic
patients. For this reason, the next best step in management of every patient with hematuria would
be a urine analysis and culture. Urologic malignancies (mostly cancer of the bladder) should be
considered and ruled out once urine culture is negative and renal stones are excluded using
ultrasound (the best initial test) or spiral CT (the most accurate test).','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"321","duplicate_group_id":"exact-05771de67aae","duplicate_sources":[{"record_id":"ad4788fe2880d60b835b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1889,"source_qid":"321"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"ad4788fe2880d60b835b","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1889,"source_qid":"321","domain_hint":"Mixed/Unclassified","stem":"During a routine health assessment, a 43-year-old man is found to have established asymptomatic\nhematuria. Which one of the following is the most appropriate next step in management?","options":{"A":"Ultrasonography of the renal system.","B":"CT scan.","C":"Cystoscopy.","D":"Urine culture.","E":"Intravenous pyelogram (IVP)."},"source_answer":"D","source_explanation":"Hematuria may be seen in a variety of situations including, but not limited to:\nInfections\nRenal stones\nGlomerulonephritis\nUrinary tract malignancies\nTrauma\nInfections are the most common cause of hematuria in both symptomatic and asymptomatic\npatients. For this reason, the next best step in management of every patient with hematuria would\nbe a urine analysis and culture. Urologic malignancies (mostly cancer of the bladder) should be\nconsidered and ruled out once urine culture is negative and renal stones are excluded using\nultrasound (the best initial test) or spiral CT (the most accurate test).","source_answer_status":"present","current_answer":null,"current_answer_status":"needs