INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('ad4788fe2880d60b835b','src-v294-687f312c','321','1889','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','During a routine health assessment, a 43-year-old man is found to have established asymptomatic
hematuria. Which one of the following is the most appropriate next step in management?',NULL,'D','Hematuria may be seen in a variety of situations including, but not limited to:
Infections
Renal stones
Glomerulonephritis
Urinary tract malignancies
Trauma
Infections are the most common cause of hematuria in both symptomatic and asymptomatic
patients. For this reason, the next best step in management of every patient with hematuria would
be a urine analysis and culture. Urologic malignancies (mostly cancer of the bladder) should be
considered and ruled out once urine culture is negative and renal stones are excluded using
ultrasound (the best initial test) or spiral CT (the most accurate test).',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"321","duplicate_group_id":"exact-05771de67aae","duplicate_sources":[{"record_id":"ad4788fe2880d60b835b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1889,"source_qid":"321"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
