INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d64eb1d0eafa9223a129','Amedex 2023.pdf','1892','Mixed/Unclassified','A 77-year-old man presents to your clinic with vague abdominal pain. Among initial laboratory
tests, hematuria is notable. A repeated urinalysis confirms hematuria. You order a 4-phase
contrasted abdominal CT scan that shows a 1cm complex mass in the lower pole of the right
kidney. He is otherwise asymptomatic, enjoys a healthy life, and do not have any comorbidities.
Which one of the following is the most appropriate inital management option for him?','{"A":"Repeat the CT scan in 12 months.","B":"Nephrectomy.","C":"CT-guided percutaneous biopsy.","D":"Reassurance.","E":"Thermal ablation."}','B','Abdominal pain and hematuria in the presence of a renal mass is renal cell carcinoma (RCC) until
proven otherwise. Small renal masses (<4 cm) can be found incidentally, or during evaluation for
urinary symptoms, often by ultrasound as the initial imaging modality. Once a mass is found in the
kidney on ultrasound, a 4-phase contrasted CT scan should follow for further evaluation if contrast
media is not contraindicated.
Solid or complex masses (a lesion demonstrating both cystic and solid structures), as well as
cystic masses enhanced with contrast are suspected to be malignant and treatment is warranted.
NOTE - By definition, a renal lesion <4 cm in its largest diameter that shows contrast
enhancement on abdominal imaging is a small renal mass. These lesions can be solid or
complex cystic. Simple cysts not enhancing with contrast are excluded.
 
If the patient is a good candidate for surgical resection and has a life expectancy >5 years, surgical
resection of the small renal mass would be the most appropriate initial management. This patient
is otherwise fit and healthy with no comorbid condition precluding him from surgical tumor
resection. Partial nephrectomy is the procedure of choice for masses less than 7cm that are not
centrally located. This is to preserve as much renal function as possible.
(Option A) Active surveillance with CT scan or MRI in 6- to 12-monht intervals is recommended for
patients with small renal masses who are not good candidates for surgical resection (e.g., have a
comorbid condition), or have a life expectancy of ≤5 years. Renal impairment may also be an
indication for active surveillance in some patients. Active surveillance means that the patient will
either have delayed treatment or no treatment at all. This patient has no comorbid condition
precluding him from tumor resection.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-62c59bb2d474","duplicate_sources":[{"record_id":"d64eb1d0eafa9223a129","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1892,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"d64eb1d0eafa9223a129","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1892,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 77-year-old man presents to your clinic with vague abdominal pain. Among initial laboratory\ntests, hematuria is notable. A repeated urinalysis confirms hematuria. You order a 4-phase\ncontrasted abdominal CT scan that shows a 1cm complex mass in the lower pole of the right\nkidney. He is otherwise asymptomatic, enjoys a healthy life, and do not have any comorbidities.\nWhich one of the following is the most appropriate inital management option for him?","options":{"A":"Repeat the CT scan in 12 months.","B":"Nephrectomy.","C":"CT-guided percutaneous biopsy.","D":"Reassurance.","E":"Thermal ablation."},"source_answer":"B","source_explanation":"Abdominal pain and hematuria in the presence of a renal mass is renal cell carcinoma (RCC) until\nproven otherwise. Small renal masses (<4 cm) can be found incidentally, or during evaluation for\nurinary symptoms, often by ultrasound as the initial imaging modality. Once a mass is found in the\nkidney on ultrasound, a 4-phase contrasted CT scan should follow for further evaluation if contrast\nmedia is not contraindicated.\nSolid or complex masses (a lesio