INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('8006f511345961637ddc','Amedex 2023.pdf','1896','Mixed/Unclassified','A 69-year-old man presents to your GP clinic with complaint of uriary incontinence. He explains
that he cannot make it to the bathroom once he feels the urge to pass urine. He denies any dysuria.
Which one of the following could be the most likeky underlying cause to this presentation?','{"A":"Benign prostatic hyperplasia (BPH).","B":"Urinary tract infection (UTI).","C":"Detrusor instability.","D":"Increased intraabdominal pressure.","E":"Nephrolithiasis."}','C','The incontinence described in the scenario is characteristic of urge incontinence. In this type of
incontinence, there is sudden and strong urge to pass urine. The patient often is not able to make it
to the bathroom and wet themselves. An overactive bladder caused by detrusor instability is the
most common etiology of urge incontinence and the most likely cause to this presentation. An
irritable or unstable bladder are synonymous terms used to describe the pathology. Patients with
detrusor instability have involuntary bladder contractions, resulting in a sudden urge to urinate.
(Option A) BPH usually causes overflow urinary incontinence rather than urge incontinence.
(Option B) Although UTI is a cause of frequency and urgency due to irritation of the bladder,
detrusor instability of unknown etiology is the most common cause of urge incontinence.
(Option D) Increased intraabdominal pressure is a cause of urine overflow in stress incontinence
not in urge incontinence.
(Option E) A stone in the bladder can irritate the bladder and cause frequency, urgency, and urge
incontinence but idiopathic detrusor instability remains the most common cause of urge
incontinence.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1256","duplicate_group_id":"exact-cb12668d4c13","duplicate_sources":[{"record_id":"8006f511345961637ddc","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1896,"source_qid":"1256"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"8006f511345961637ddc","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1896,"source_qid":"1256","domain_hint":"Mixed/Unclassified","stem":"A 69-year-old man presents to your GP clinic with complaint of uriary incontinence. He explains\nthat he cannot make it to the bathroom once he feels the urge to pass urine. He denies any dysuria.\nWhich one of the following could be the most likeky underlying cause to this presentation?","options":{"A":"Benign prostatic hyperplasia (BPH).","B":"Urinary tract infection (UTI).","C":"Detrusor instability.","D":"Increased intraabdominal pressure.","E":"Nephrolithiasis."},"source_answer":"C","source_explanation":"The incontinence described in the scenario is characteristic of urge incontinence. In this type of\nincontinence, there is sudden and strong urge to pass urine. The patient often is not able to make it\nto the bathroom and wet themselves. An overactive bladder caused by detrusor instability is the\nmost common etiology of urge incontinence and the most likely cause to this presentation. An\nirritable or unstable bladder are synonymous terms used to describe the pathology. Patients with\ndetrusor instability have involuntary bladder contractions, resulting in a sudden urge to urinate.\n(Option A) BPH usually causes overflow urinary incontinence rather than urge incontinence.\n(Option B) Although UTI is a cause of frequency and urgency due to irritation of the bladder,\ndetrusor instability of unknown etiology is the most common cause of urge incontinence.\n(Option D) Increased intraabdominal pressure is a cause of urine overflow in stress incontinence\nnot in urge incontinence.\n(Option E) A stone in the bladder can irritate the bladder and cause frequency, urgency, and urge\nincontinence but idiopathic detrusor instability remains the most common cause of urge\nincontinence.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"cb12668d4c13cd01c5ee8b1f7d27a92c9044cb36","duplicate_group_id":"exact-cb12668d4c13","duplicate_sources":[{"record_id":"8006f511345961637ddc","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1896,"source_qid":"1256"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_v