INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('e7a97f3625cda8aa8dda','Amedex 2023.pdf','1897','Mixed/Unclassified','A 70-year-old man presents to the Emergency Department with complaint of intermittent loin pain
for the past 48 hours. On examination, he is afebrile and there is no tenderness over the loin, flank
or costovertebral angle. A urine test shows 3+ hematuria with negativity for protein and nitrite.
Which one of the following is the most appropriate next step in management?','{"A":"Abdominal X-ray.","B":"Intravenous pyelogram (IVP).","C":"Abdominal CT scan.","D":"Retrograde pyelography.","E":"Urine culture."}','C','The scenario is highly suggestive of kidney stone(s) (nephrolithiasis) as the most likely diagnosis.
Nephrolithiasis affects one in 10 persons in Australia. Although most stones pass spontaneously,
some conditions require intervention. These conditions include:
Continuous pain
Renal impairment
Urinary tract infections
For every patient presenting with a clinical picture suggestive of urinary stones, investigations
should be considered to determine the location, number and size of the stone(s) which influence its
likelihood of spontaneous passage.
Non-contrast CT scan of the abdomen for assessment of the kidneys, ureters and bladder (CT-KUB)
is the investigation of choice to consider. CT-KUB has a sensitivity and specificity of approximately
100% for evaluation of urinary stones irrespective of stone type. It also provides an opportunity for
an alternative diagnosis if no stone(s) is visualized. It is important to note that an additional KUB
plain film (x-ray) should be obtain at the same presentation. If the stone is visible on plain KUB, this
can be used for follow up imaging, with a lower radiation dose. Only calcium-containing stones are
visible on plain KUB X-ray, and this information also has implications for stone management.
(Option A) As mentioned above, a KUB x-ray is performed for reducing the radiation exposure
associate with CT scanning if the stone is visualized. Otherwise, this modality is not sensitive
enough to establish a diagnosis.
(Option B) Intravenous pyelogram (IVP) is used rarely in the diagnosis of ureteric colic due to the
high sensitivity and specificity of non-contrast CT KUB. However, a contrast study (CT urogram)
may be helpful sometimes for treatment planning purposes. Retrograde pyelography (option C)
serves the same purpose as does IVP but the contrast material is pushed up through a urinary
catheter. This test has no role for evaluation of patients with real colic.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-da9c51a53b17","duplicate_sources":[{"record_id":"e7a97f3625cda8aa8dda","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1897,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"e7a97f3625cda8aa8dda","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1897,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 70-year-old man presents to the Emergency Department with complaint of intermittent loin pain\nfor the past 48 hours. On examination, he is afebrile and there is no tenderness over the loin, flank\nor costovertebral angle. A urine test shows 3+ hematuria with negativity for protein and nitrite.\nWhich one of the following is the most appropriate next step in management?","options":{"A":"Abdominal X-ray.","B":"Intravenous pyelogram (IVP).","C":"Abdominal CT scan.","D":"Retrograde pyelography.","E":"Urine culture."},"source_answer":"C","source_explanation":"The scenario is highly suggestive of kidney stone(s) (nephrolithiasis) as the most likely diagnosis.\nNephrolithiasis affects one in 10 persons in Australia. Although most stones pass spontaneously,\nsome conditions require intervention. These conditions include:\nContinuous pain\nRenal impairment\nUrinary tract infections\nFor every patient presenting with a clinical picture suggestive of urinary stones, investigations\nshould be considered to determine the location, number and size of the stone(s) which