INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a35d367684d989d19105','Amedex 2023.pdf','1899','Mixed/Unclassified','An 85-year-old woman presents with complaint of leakage of small amounts of urine when she
laughs, coughs, or sneezes. On examination, she has a reducible rectocele. As the most
appropriate initial step in management you advise bladder training and pelvic floor muscle exercise
that fails to improve her symptoms. Which one of the following is the most appropriate next step in
management?','{"A":"Vaginal cones.","B":"Imipramine.","C":"Surgical repair of the rectocele.","D":"Bladder neck suspension.","E":"Vaginal estrogen cream."}','D','The scenario is a typical case of stress urinary incontinence. Stress incontinence is the most
common cause of urinary incontinence in younger women and the second most common cause in
older women (after mixed incontinence), and occurs when an increase in intraabdominal pressure
overcomes sphincter closure mechanisms in the absence of a bladder contraction.
Pelvic floor muscles exercise is the initial therapy in women with stress and mixed incontinence,
and also useful, in combination with bladder training, for women with urge incontinence. If pelvic
floor muscle training fails, the mainstay of treatment is surgery. Surgery has high cure rates for
stress urinary incontinence, even in elderly women. A vaginal or abdominal approach can be used
for surgical treatment. Vaginal procedures include mid-urethral sling (insertion of a tension-free
vaginal tape under the urether), bladder neck sling (suspension), or injection of urethral bulking
agents. Burch''s retropubic colposuspension is an abdominal procedure for stress urinary
incontinence and is more invasive prcedure compared with other surgical methods.
NOTE - Insertion of a tension-free vaginal tape (midurethral sling) was the preferred correct answer
if among options. This procedure is simple and minimally invasive. The procedrue is shown in the
following video:','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-35ec97bd6173","duplicate_sources":[{"record_id":"a35d367684d989d19105","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1899,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"a35d367684d989d19105","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1899,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"An 85-year-old woman presents with complaint of leakage of small amounts of urine when she\nlaughs, coughs, or sneezes. On examination, she has a reducible rectocele. As the most\nappropriate initial step in management you advise bladder training and pelvic floor muscle exercise\nthat fails to improve her symptoms. Which one of the following is the most appropriate next step in\nmanagement?","options":{"A":"Vaginal cones.","B":"Imipramine.","C":"Surgical repair of the rectocele.","D":"Bladder neck suspension.","E":"Vaginal estrogen cream."},"source_answer":"D","source_explanation":"The scenario is a typical case of stress urinary incontinence. Stress incontinence is the most\ncommon cause of urinary incontinence in younger women and the second most common cause in\nolder women (after mixed incontinence), and occurs when an increase in intraabdominal pressure\novercomes sphincter closure mechanisms in the absence of a bladder contraction.\nPelvic floor muscles exercise is the initial therapy in women with stress and mixed incontinence,\nand also useful, in combination with bladder training, for women with urge incontinence. If pelvic\nfloor muscle training fails, the mainstay of treatment is surgery. Surgery has high cure rates for\nstress urinary incontinence, even in elderly women. A vaginal or abdominal approach can be used\nfor surgical treatment. Vaginal procedures include mid-urethral sling (insertion of a tension-free\nvaginal tape under the urether), bladder neck sling (suspension), or injection of urethral bulking\nagents. Burch''s retropubic colposuspension is an abdominal procedure for stress urinary\nincontinence and is more invasive prcedure compared with other surgical methods.\nNOTE - Insertion of a tension-free vaginal tape (midurethral sling) was the preferred correct answer\nif among options. This procedure is simple and minimally invasive. The procedrue is shown in the\nfollowing video:","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"35ec97bd6173723f8165b6b7e165a4312d4978e6","duplicate_group_id":"exact-35ec97bd6173","duplicate_sources":[{"record_id":"a35d367684d989d19105","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1899,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.c