INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('25d497884e9ebaa47494','Amedex 2023.pdf','1902','Mixed/Unclassified','A 70-year-old woman come to your clinic with complaint of urinary incontinence. She describes her
problem as leakage of small amounts of urine when she laughs, sneezes or coughs, as well as
during exercise. Which one of the following is the most appropriate next step in management?','{"A":"Pelvic floor mucles exercise.","B":"Tension-free vaginal tape.","C":"Burch''s colposuspension.","D":"Vaginal weighted cones.","E":"Topical estrogen cream."}','A','The description is typical for genuine stress urinary incontinence (SUI) as the most likely diagnosis.
For women, who present with SUI or mixed incontinence, pelvic floor exercise is the most
appropriate management option to consider first.
Bladder training is the most important component of treatment in mixed incontinence with
pronounced symptoms related to an overactive bladder. Pelvic floor muscle exercise strengthens
the muscular components of the urethral closure mechanism. The basic recommended regimen is
3 sets of 8 to 12 slow velocity contractions sustained for 6 to 8 seconds each, performed 3 or 4
times a week and continued for at least 3 months.
(Options B and C) Tension free vaginal tape and Burch’s colposuspension are more invasive
procedures considered for patients who fail to respond to conservative management strategies.
Tension free vaginal tape is a minimally invasive procedure that is performed by transcutaneous
placement of a mesh around and under the mid-urethra. It does not elevate the urethra and rather
forms a resistant platform against intraabdominal pressure. In Burch’s procedure, an
intraabdominal approach is used to lift the bladder neck upwards using stitches.
(Option D) Weighted vaginal cones are used as supplement to pelvic floor muscle exercise. The
patient inserts the cone in her vagina and uses pelvic muscle contractions to hold it in place during
activity. Although small trials show efficacy compared with no treatment in younger women, it is
unclear if outcomes are comparable to other therapies. . A 2013 systematic review and meta-
analysis of 23 small randomized trials found some evidence that cones have increased efficacy
over no active treatment, but inconclusive evidence that they provide increased efficacy over
standard pelvic floor muscle exercise.
(Option E) Topical estrogen therapy has been used, as a supplement to pelvic floor exercise, in
postmenopausal women with urge and mixed incontinence. It is possible that urinary urgency and
frequency in urge incontinence are symptoms of urogenital atrophy in older postmenopausal
women. There is good evidence that low-dose topical vaginal estrogen therapy may reverse the
symptoms and cytologic changes of urogenital atrophy. However, oral estrogens (with or without
progesterone) have been shown to worsen urinary incontinence, and should be avoided. Evidence
supporting the use of estrogen for patients with stress urinary incontinence is insufficient.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-ea38d706902d","duplicate_sources":[{"record_id":"25d497884e9ebaa47494","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1902,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"25d497884e9ebaa47494","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1902,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 70-year-old woman come to your clinic with complaint of urinary incontinence. She describes her\nproblem as leakage of small amounts of urine when she laughs, sneezes or coughs, as well as\nduring exercise. Which one of the following is the most appropriate next step in management?","options":{"A":"Pelvic floor mucles exercise.","B":"Tension-free vaginal tape.","C":"Burch''s colposuspension.","D":"Vaginal weighted cones.","E":"Topical estrogen cream."},"source_answer":"A","source_explanation":"The description is typical for genuine stress urinary incontinence (SUI) as the most likely diagnosis.\nFor women, who present with SUI or mixed incontinence, pelvic floor exercise is the most\nappropriate management option to consider first.\nBladder training is the most important component of treatment in mixed incontinence with\npronounced symptoms related to an overactive bladder. Pelvic floor muscle exercise strengthens\nthe muscular components of the urethral closure mechanism. The basic recommended regimen is\n3 sets of 8 to 12 slow velocity contractions sustained for 6 to 8 seconds each, performed 3 or 4\ntimes a week and continued for at least 3 months.\n(Options B and C) Tension free vaginal tape and Burch’s colposuspension are more invasive\nprocedures considered for patients who fail to respond to conservative management strategies.\nTension free vaginal tape is a minimally invasive procedure that is performed by transcutaneous\nplacement of a mesh around and under the mid-urethra. It does not elevate the urethra and rather\nforms a resistant platform against intraabdominal pressure. In Burch’s procedure, an\nintraabdominal approach is used to lift the bladder neck upwards using stitches.\n(Option D) Weighted vaginal cones are used as supplement to pelvic floor muscle exercise. The\npatient inserts the cone in her vagina and uses pelvic muscle contractions to hold it in place during\nactivity. Although small trials show efficacy compared with no treatment in younger women, it is\nunclear if outcomes are comparable to other therapies. . A 2013 systematic review and meta-\nanalysis of 23 small randomized trials found some evidence that cones have increased efficacy\nover no active treatment, but inconclusive evidence that they provide increased efficacy over\nstandard pelvic floor muscle exercise.\n(Option E) Topical estrogen therapy has been used, as a supplement to pelvic floor exercise, in\npostmenopausal women with urge and mixed incontinence. It is possible that urinary urgency and\nfrequency in urge incontinence are symptoms of urogenital atrophy in older postmenopausal\nwomen. There is good evidence that low-dose topical vaginal estrogen therapy may reverse the\nsymptoms and cytologic changes of urogenital atrophy. However, oral estrogens (with or without\nprogesterone) have been shown to worsen urinary incontinence, and should be avoided. Evidence\nsupporting the use of estrogen for patients with stress urinary incontinence is insufficient.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","dose","management","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"ea38d706902d9c414a89cedddf206153699350cb","duplicate_group_id":"exact-ea38d706902d","duplicate_sources":[{"record_id":"25d497884e9ebaa47494","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1902,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
