INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('250c5f0987cfca256ff0','Amedex 2023.pdf','1904','Mixed/Unclassified','A 75-year-old woman presents with leakage of urine when she laughs, sneezes, coughs or lifts
heavy weights. She also complains that she feels the urge to pass urine 10-12 times a day, and half
of time she cannot make it to the bathroom. Urgency appears to be more troublesome for her. A
urine examination is negative for infections. Ultrasound scan of the bladder, ureter and kidneys is
inconclusive, except a residual volume of 125cc. Which one of the following is the most appropriate
treatment option for her?','{"A":"Anticholinergic medications.","B":"Anterior colporrhaphy.","C":"Retropubic suspension of the bladder.","D":"Pelvic floor muscle exercise.","E":"Bladder training."}','E','This woman has signs and symptoms of both stress incontinence and urge incontinence, namely
mixed incontinence. However, she is annoyed mostly by the urge. For women with urge continence
as the most bothersome symptom, bladder training would be the most appropriate management
option to consider first. The goals are:
Establishing a baseline with a bladder diary
Establishing a voiding interval
Gradually increasing the voiding interval in increments such as 2–5 minutes over a prolonged
time period aiming to void every 3 hours
Other important measures to consider are lifestyle modifications such as decreased fluid intake,
weight reduction and avoiding certain foods and beverages that have diuretics effects (e.g.,
alcoholic beverages, caffeine, etc).
(Option A) Anticholinergics, combined with continued bladder training, are an option when urge
incontinence does not respond to physical or behavioral therapies. A trial of 4 to 6 weeks is used.
For those who respond, risk and benefits are balanced at 6 months to determine whether treatment
should be continued. Patients should be advised about the adverse effects of anticholinergics such
as dry mouth and constipation, and how to manage them.
(Option B) Anterior coloprrhaphy is a repair of the front vaginal wall to treat cystocele and can help
women who suffer from urinary incontinence. Without a cystocele, bladder neck suspension is the
treatment of choice.
(Option C) Retropubic suspension of the bladder is a more invasive procedure used for treatment
of stress urinary incontinence in patients who has failed to respond to more conservative
measures such as pelvic floor exercise.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-823591a04f83","duplicate_sources":[{"record_id":"250c5f0987cfca256ff0","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1904,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"250c5f0987cfca256ff0","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1904,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 75-year-old woman presents with leakage of urine when she laughs, sneezes, coughs or lifts\nheavy weights. She also complains that she feels the urge to pass urine 10-12 times a day, and half\nof time she cannot make it to the bathroom. Urgency appears to be more troublesome for her. A\nurine examination is negative for infections. Ultrasound scan of the bladder, ureter and kidneys is\ninconclusive, except a residual volume of 125cc. Which one of the following is the most appropriate\ntreatment option for her?","options":{"A":"Anticholinergic medications.","B":"Anterior colporrhaphy.","C":"Retropubic suspension of the bladder.","D":"Pelvic floor muscle exercise.","E":"Bladder training."},"source_answer":"E","source_explanation":"This woman has signs and symptoms of both stress incontinence and urge incontinence, namely\nmixed incontinence. However, she is annoyed mostly by the urge. For women with urge continence\nas the most bothersome symptom, bladder training would be the most appropriate management\noption to consider first. The goals are:\nEstablishing a baseline with a bladder diary\nEstablishing a voiding interval\nGradually increasing the voiding interval in increments such as 2–5 minutes over a prolonged\ntime period aiming to void every 3 hours\nOther important measures to consider are lifestyle modifications such as decreased fluid intake,\nweight reduction and avoiding certain foods and beverages that have diuretics effects (e.g.,\nalcoholic beverages, caffeine, etc).\n(Option A) Anticholinergics, combined with continued bladder training, are an option when urge\nincontinence does not respond to physical or behavioral therapies. A trial of 4 to 6 weeks is used.\nFor those who respond, risk and benefits are balanced at 6 months to determine whether treatment\nshould be continued. Patients should be advised about the adverse effects of anticholinergics such\nas dry mouth and constipation, and how to manage them.\n(Option B) Anterior coloprrhaphy is a repair of the front vaginal wall to treat cystocele and can help\nwomen who suffer from urinary incontinence. Without a cystocele, bladder neck suspension is the\ntreatment of choice.\n(Option C) Retropubic suspension of the bladder is a more invasive procedure used for treatment\nof stress urinary incontinence in patients who has failed to respond to more conservative\nmeasures such as pelvic floor exercise.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","interval","management","treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"823591a04f830f615dad8f9882cfa700c981ed4a","duplicate_group_id":"exact-823591a04f83","duplicate_sources":[{"record_id":"250c5f0987cfca256ff0","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1