INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('16204b8947a1da381f67','Amedex 2023.pdf','1906','Mixed/Unclassified','A 65-year-old woman presents to your practice with complaint of urinary incontinence that has
restricted her social activities. She feels the urge to urinate while outside and often cannot make it
to a bathroom. She also mentions that every time she puts the key into the door, it is like that her
bladder wakes up and get irritated. Which one of the following would be the most appropriate
advice for her at this stage?','{"A":"Pelvic floor muscles exercises.","B":"Anticholinergic medications.","C":"Bladder training.","D":"Vaginal cones.","E":"Bladder neck suspension."}','C','The case scenario represents a typical case of urge urinary incontinence. For women with mild to
moderate stress, urge and mixed urinary incontinence, behavioral and physical therapy should be
the initial treatment. It also can be an option for patients with more severe symptoms. These
therapies include bladder training and pelvic floor muscle exercise (Kegel exercise). Although these
two are often used in combination, pelvic floor muscle exercises are recommended initially for
genuine stress incontinence and the stress component of mixed incontinence. On the other hand,
bladder training is the first line-treatment for urge incontinence. It should be noted, however, that
these two are usually advised in combination. This woman has urge incontinence; therefore,
bladder training is first-line option for her treatment.
The goals of bladder training are:
Establishing a baseline with a bladder diary
Establishing a voiding interval
Gradually increasing the voiding interval in increments such as 2–5 minutes over a prolonged
time period aiming to void every 3 hours
(Option A) Pelvic floor muscles exercise is also an important part to consider in conservative
management in combination with bladder training; however, not as effective as bladder training in
urge incontinence.
(Option C) Anticholinergics, combined with continued bladder training, are an option when urge
incontinence does not respond to physical or behavioral therapies. A trial of 4 to 6 weeks is used.
For those who respond, risk and benefits are balanced at 6 months to determine if treatment
should be continued. Patients should be advised about the adverse effects of anticholinergics such
as dry mouth and constipation, and how to manage them.
(Option D) Vaginal cones are used as supplement to pelvic muscle exercise for treatment of stress
urinary incontinence. The patient inserts the cone in her vagina and uses pelvic muscle','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-06aef9fa48ec","duplicate_sources":[{"record_id":"16204b8947a1da381f67","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1906,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"16204b8947a1da381f67","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1906,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 65-year-old woman presents to your practice with complaint of urinary incontinence that has\nrestricted her social activities. She feels the urge to urinate while outside and often cannot make it\nto a bathroom. She also mentions that every time she puts the key into the door, it is like that her\nbladder wakes up and get irritated. Which one of the following would be the most appropriate\nadvice for her at this stage?","options":{"A":"Pelvic floor muscles exercises.","B":"Anticholinergic medications.","C":"Bladder training.","D":"Vaginal cones.","E":"Bladder neck suspension."},"source_answer":"C","source_explanation":"The case scenario represents a typical case of urge urinary incontinence. For women with mild to\nmoderate stress, urge and mixed urinary incontinence, behavioral and physical therapy should be\nthe initial treatment. It also can be an option for patients with more severe symptoms. These\ntherapies include bladder training and pelvic floor muscle exercise (Kegel exercise). Although these\ntwo are often used in combination, pelvic