INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4530d3eb9a231f9cb833','Amedex 2023.pdf','1908','Mixed/Unclassified','A 58-year-old woman presents to your practice with the complaint that she loses control of her
‘waterworks’ when she puts her key in the front door. She denies urinary leakage associated with
laughing, coughing, or sneezing. Which form of urinary incontinence is she most likely to have?','{"A":"Incontinence from a urinary fistula.","B":"Stress incontinence.","C":"Urge incontinence.","D":"Incontinence secondary to a neuropathic bladder.","E":"Overflow incontinence."}','C','The patient’s description of incontinence is consistent with urge incontinence as the most likely
diagnosis. Urge incontinence occurs when the patient is unable to delay micturition. The condition
may be precipitated by various triggers such as the sound of running water or placing a key in the
door when arriving home.
(Option A) urinary fistula is associated with continuous dribbling or leakage of small amounts of
urine on effort.
(Option B) Stress incontinence is associated with leakage of usually small amounts of urine during
activities that cause the intra-abdominal pressure to increase e.g., coughing or sneezing, which this
patient denies. 
(Option D) Neuropathic (neurogenic) bladder refers to bladder dysfunction secondary to neurologic
damage. Symptoms can include overflow incontinence, frequency, urgency, urge incontinence, and
urinary retention. Although a neurogenic bladder may lead to urge incontinence, it is the cause
rather than the type of the incontinence.
(Option E) Overflow incontinence is due to obstruction and may be secondary to uterovaginal
prolapse or a hypotonic bladder as in a neuropathic bladder.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1294","duplicate_group_id":"exact-f372e6ab022c","duplicate_sources":[{"record_id":"4530d3eb9a231f9cb833","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1908,"source_qid":"1294"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"4530d3eb9a231f9cb833","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1908,"source_qid":"1294","domain_hint":"Mixed/Unclassified","stem":"A 58-year-old woman presents to your practice with the complaint that she loses control of her\n‘waterworks’ when she puts her key in the front door. She denies urinary leakage associated with\nlaughing, coughing, or sneezing. Which form of urinary incontinence is she most likely to have?","options":{"A":"Incontinence from a urinary fistula.","B":"Stress incontinence.","C":"Urge incontinence.","D":"Incontinence secondary to a neuropathic bladder.","E":"Overflow incontinence."},"source_answer":"C","source_explanation":"The patient’s description of incontinence is consistent with urge incontinence as the most likely\ndiagnosis. Urge incontinence occurs when the patient is unable to delay micturition. The condition\nmay be precipitated by various triggers such as the sound of running water or placing a key in the\ndoor when arriving home.\n(Option A) urinary fistula is associated with continuous dribbling or leakage of small amounts of\nurine on effort.\n(Option B) Stress incontinence is associated with leakage of usually small amounts of urine during\nactivities that cause the intra-abdominal pressure to increase e.g., coughing or sneezing, which this\npatient denies. \n(Option D) Neuropathic (neurogenic) bladder refers to bladder dysfunction secondary to neurologic\ndamage. Symptoms can include overflow incontinence, frequency, urgency, urge incontinence, and\nurinary retention. Although a neurogenic bladder may lead to urge incontinence, it is the cause\nrather than the type of the incontinence.\n(Option E) Overflow incontinence is due to obstruction and may be secondary to uterovaginal\nprolapse or a hypotonic bladder as in a neuropathic bladder.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"f372e6ab022c6f0e100bedb2fe33c6dc2b7f3242","duplicate_group_id":"exact-f372e6ab022c","duplicate_sources":[{"record_id":"4530d3eb9a231f9cb833","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1908,"source_qid":"1294"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_