INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b061cdbf5e9b043c5100','Amedex 2023.pdf','1910','Mixed/Unclassified','A 58-year-old man is brought to the emergency department with an ambulance due to confusion at
home notice by his wife. He is a known case of chronic kidney disease (CKD), hypertension and
congestive heart failure (CHF). He is currently on carvedilol 6.25mg BD, Ramipril 10mg BD, aspirin
100mg daily and atorvastatin 10mg daily. On examination, he has a blood pressure of
148/97mmHg, pulse rate of 98bpm, respiratory rate of 21 breaths per minute and temperature of
37.3°C. He is confused and disoriented to time, place and person. Laboratory tests for him are
ordered, of which the results for his urea and electrolytes are as follows:
Urea: 18mmol/L (2.9-8.2 mmol/L)
Creatinine: 9 mmol/L (up to 0.11mmol/L in males; up to 0.9mmol/L in males)
Calcium: 3.1 mmol/L (2.10-2.50mmol/L)
Phosphate: 3.5 mmol/L (1-1.5mmol/L)
Sodium: 128mmol/L (135-145mmol/L)
Potassium: 5.7 mmol/L (3.5-5.1mmol/L)
Which one of the following could be the most likely cause of his confusion?','{"A":"Hyperphosphatemia.","B":"Hyponatremia.","C":"Hyperkalemia.","D":"Uremia.","E":"Hypercalcemia."}','D','Of the options, elevated levels of serum urea are most likely to have contributed to this
presentation.
Given the very high levels of serum urea and creatinine in this patient, he is most likely suffering
from uremic encephalopathy. Early symptoms of uremic encephalopathy include the following:
Anorexia
Nausea
Restlessness
Drowsiness
Diminished ability to concentrate
Slowed cognitive functions
More severe signs and symptoms of uremic encephalopathy include the following:
Vomiting
Emotional volatility
Decreased cognitive function
Disorientation','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-5f9b5a693899","duplicate_sources":[{"record_id":"b061cdbf5e9b043c5100","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1910,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"b061cdbf5e9b043c5100","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1910,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 58-year-old man is brought to the emergency department with an ambulance due to confusion at\nhome notice by his wife. He is a known case of chronic kidney disease (CKD), hypertension and\ncongestive heart failure (CHF). He is currently on carvedilol 6.25mg BD, Ramipril 10mg BD, aspirin\n100mg daily and atorvastatin 10mg daily. On examination, he has a blood pressure of\n148/97mmHg, pulse rate of 98bpm, respiratory rate of 21 breaths per minute and temperature of\n37.3°C. He is confused and disoriented to time, place and person. Laboratory tests for him are\nordered, of which the results for his urea and electrolytes are as follows:\nUrea: 18mmol/L (2.9-8.2 mmol/L)\nCreatinine: 9 mmol/L (up to 0.11mmol/L in males; up to 0.9mmol/L in males)\nCalcium: 3.1 mmol/L (2.10-2.50mmol/L)\nPhosphate: 3.5 mmol/L (1-1.5mmol/L)\nSodium: 128mmol/L (135-145mmol/L)\nPotassium: 5.7 mmol/L (3.5-5.1mmol/L)\nWhich one of the following could be the most likely cause of his confusion?","options":{"A":"Hyperphosphatemia.","B":"Hyponatremia.","C":"Hyperkalemia.","D":"Uremia.","E":"Hypercalcemia."},"source_answer":"D","source_explanation":