INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a951377f0bdcafb7d0ad','Amedex 2023.pdf','1913','Mixed/Unclassified','A 65-year-old man presents to your GP clinic with long-standing history of difficulty starting voiding
and terminal dribbling and, recently, nocturia. Abdominal examination reveals a dull mass over the
suprapubic area. On digital rectal exam (DRE), the prostate is enlarged but smooth with palpable
median sulcus. Which one of the following is the most appropriate next step in management of this
patient?','{"A":"Serum creatinine level.","B":"Transrectal ultrasonography (TURS).","C":"CT scan of the abdomen.","D":"PSA.","E":"Urine cytology."}','A','This patient has characteristic features of lower urinary tract symptoms (LUTS). LUTS can present
with voiding symptoms (bladder emptying) such as weak urine stream, hesitancy (difficulty starting
urination) or intermittency of follow, or with storage (bladder filling) symptoms such as urgency,
daytime frequency and nocturia.
Predominance of storage symptoms requires exclusion of conditions such as primary bladder
pathology/ malignancy, diabetes mellitus, and medications with diuretic effects. Where nocturia is
the presenting symptom, nocturnal polyuria should be excluded too.
Based on the international guidelines, it is important to determine the severity of LUTS and to
identify the complicating factors such as urinary retention, macroscopic hematuria, urinary tract
infections or a personal or family history of prostate cancer.
For every patient presenting with LUTS, initial investigations should be considered to exclude
sinister causes LUTS or complications associated with bladder outflow obstruction. These
investigations include:
Urinalysis - excluding hematuria, proteinuria, or pyuria - follow up with urine culture is required
if there is abnormality on urinalysis
Serum creatinine and estimated glomerular filtration rate (eGFR) - this test is required for
exclusion of renal injury from primary renal dysfunction or high-pressure bladder outflow
obstruction.
Urinary tract ultrasound - assessment of prostate volume, bladder wall and residual urine and
exclusion of hydronephrosis
Prostate specific antigen to exclude prostate cancer - most guidelines recommend the use of
serum PSA only if prostate cancer diagnosis will influence management or if the test will
assist in decision making
Urinary symptoms of this man and the presence of an enlarged prostate on DRE make benign
prostatic hyperplasia (BPH) the most likely diagnosis. Additionally, the dull mas over the','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-29b840c05e92","duplicate_sources":[{"record_id":"a951377f0bdcafb7d0ad","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1913,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"a951377f0bdcafb7d0ad","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1913,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 65-year-old man presents to your GP clinic with long-standing history of difficulty starting voiding\nand terminal dribbling and, recently, nocturia. Abdominal examination reveals a dull mass over the\nsuprapubic area. On digital rectal exam (DRE), the prostate is enlarged but smooth with palpable\nmedian sulcus. Which one of the following is the most appropriate next step in management of this\npatient?","options":{"A":"Serum creatinine level.","B":"Transrectal ultrasonography (TURS).","C":"CT scan of the abdomen.","D":"PSA.","E":"Urine cytology."},"source_answer":"A","source_explanation":"This patient has characteristic features of lower urinary tract symptoms (LUTS). LUTS can present\nwith voiding symptoms (bladder emptying) such as weak urine stream, hesitancy (difficulty starting\nurination) or intermittency of follow, or with storage (bladder filling) symptoms such as urgency,\ndaytime frequency and nocturia.\nPredominance of storage symptoms requires exclusion of conditions such as primary bladder\npathology/ malignancy, diabetes mell