INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('236370439d97039edf2b','Amedex 2023.pdf','1920','Mixed/Unclassified','Urinary incontinence can be categorized as:
Type of Incontinence
Cause
SUI (stress urinary
incontinence)
Weakness in the urinary sphincter and/or pelvic floor
Urge urinary incontinence
(UUI)
Detrusor overactivity i.e. a bladder muscle that
contracts involuntarily, usually at low bladder
volumes and with little warning.
Mixed urinary incontinence
(MUI) (a combination of
SUI and UUI)
A combination of stress and urge incontinence. It is
important to define which symptom is predominant
and most bothersome to the patient and treat this
symptom first.
Overflow urinary
incontinence (OUI)
Occurs when the patient is in chronic urinary
retention due to leakage from an overdistended
bladder in the setting of either bladder outlet
obstruction and/or poor bladder muscle function.
Fistula related urinary
incontinence
Fistulous connections can occur between the
bladder and vagina, ureter or urethra. Obstetric
trauma is the most common cause of vesico-vaginal
fistula worldwide. In Australia the most common
cause of vesico-vaginal fistula is iatrogenic, caused
by unidentified bladder injury usually at the time of
hysterectomy.
Functional incontinence
The involuntary loss of urine caused by either
physical limitations such as poor mobility or
cognitive disability (such as dementia) that results in
an inability to toilet normally.
Table modified by Karen McKertich from her article ''Urinary Incontinence-Assessment in
women: stress, urge or both?',NULL,NULL,NULL,'{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[1920],"source_qid":"1409","duplicate_group_id":"exact-30ae4f12174f","duplicate_sources":[{"record_id":"236370439d97039edf2b","record_type":"visual_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1920,"source_qid":"1409"}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","visual_asset":"visual_assets/Amedex_2023__73a208604f57/page_01920.jpg","asset_preview_url":"https://drive.google.com/file/d/1-0Ur8eeMJqOZG9D19BedDkhxjMKLFe3u/preview"}','visual_assets/Amedex_2023__73a208604f57/page_01920.jpg','https://drive.google.com/thumbnail?id=1-0Ur8eeMJqOZG9D19BedDkhxjMKLFe3u&sz=w1600','source_page_image',NULL,'needs_verification','[]','medium','{"record_id":"236370439d97039edf2b","record_type":"visual_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1920,"supporting_pages":[1920],"source_qid":"1409","domain_hint":"Mixed/Unclassified","stem":"Urinary incontinence can be categorized as:\nType of Incontinence\nCause\nSUI (stress urinary\nincontinence)\nWeakness in the urinary sphincter and/or pelvic floor\nUrge urinary incontinence\n(UUI)\nDetrusor overactivity i.e. a bladder muscle that\ncontracts involuntarily, usually at low bladder\nvolumes and with little warning.\nMixed urinary incontinence\n(MUI) (a combination of\nSUI and UUI)\nA combination of stress and urge incontinence. It is\nimportant to define which symptom is predominant\nand most bothersome to the patient and treat this\nsymptom first.\nOverflow urinary\nincontinence (OUI)\nOccurs when the patient is in chronic urinary\nretention due to leakage from an overdistended\nbladder in the setting of either bladder outlet\nobstruction and/or poor bladder muscle function.\nFistula related urinary\nincontinence\nFistulous connections can occur between the\nbladder and vagina, ureter or urethra. Obstetric\ntrauma is the most common cause of vesico-vaginal\nfistula worldwide. In Australia the most common\ncause of vesico-vaginal fistula is iatrogenic, caused\nby unidentified bladder injury usually at the time of\nhysterectomy.\nFunctional incontinence\nThe involuntary loss of urine caused by either\nphysical limitations such as poor mobility or\ncognitive disability (such as dementia) that results in\nan inability to toilet normally.\nTable modified by Karen McKertich from her article ''Urinary Incontinence-Assessment in\nwomen: stress, urge or both?","options":null,"options_mode":"source_page_image","visual_asset":"visual_assets/Amedex_2023__73a208604f57/page_01920.jpg","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","stem_hash":"30ae4f12174fe9b4fe808c33d8ee0c1dce983116","duplicate_group_id":"exact-30ae4f12174f","duplicate_sources":[{"record_id":"236370439d97039edf2b","record_type":"visual_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1920,"source_qid":"1409"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenanc