INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('8f71d8085f45fd9cc301','Amedex 2023.pdf','1923','Mixed/Unclassified','A 22-year-old man presents to the Emergency Department with cough and dyspnea of one week
duration, as well as fatigue, decreased urine output and dark-colored urine. Physical examination is
otherwise inconclusive. Which one of the following is the single most accurate investigation to
establish a diagnosis?','{"A":"Chest X-ray.","B":"Renal biopsy.","C":"Anti-glomerular basement membrane antibody.","D":"Urine analysis.","E":"High-resolution CT (HRCT) scan of the chest"}','B','In this patient, simultaneity of lung involvement symptoms (cough and dyspnea) and renal
involvement symptoms makes Goodpasture syndrome, also called anti-glomerular basement
membrane disease (anti-GBM disease) the most likely diagnosis. The disease may affect all age
groups but is much more common in those younger than 30 years of age. Pulmonary
manifestations of the disease include shortness of breath, cough and sometimes excessive
hemopysis due to alveolar hemorrhage.
NOTE - Lung involvement, specifically alveolar hemorrhage, can be seen with other acute
nephritides due to pulmonary edema, or due to lung involvement in ANCA positive and other
forms of systemic vasculitis, and lupus. In the latter however, other clinical findings in addition
to lung and kidney symptoms would be expected. For example, it is unlikely that lupus affects
only the lungs and the kidneys, whereas Goodpasture syndrome almost always affects the
kidneys and the lungs only.
For this patient a urine analysis (option D) and chest x-ray (option A) should be order as the initial
workup. Urine analysis in patients with Goodpasture disease usually shows the typical picture of
glomerulonephritis including proteinuria (usually not in nephrotic range), dysmorphic red cells,
white cells, and red cell and granular casts. These findings, however, indicates glomerulonephritis
without delineating a specific etiology. Chest X-ray in patients with the disease shows pulmonary
infiltrates which indicates pulmonary involvement but again without a specific cause. HRCT (option
E) can be considered for a detailed assessment of the lungs.
The criterion standard for Goodpasture disease is detection of anti-GBM antibodies either in the
serum or in the kidneys. Renal biopsy should be performed in all patients with suspected
Goodpasture syndrome unless it is contraindicated because serologic assay is variable in such
patients. Light microscopy of the specimen from biopsy often shows crescentic
glomerulonephritis, whereas immunofluorescence microscopy reveals the pathognomonic finding
of linear deposition of IgG along the glomerular capillaries and occasionally the distal tubules. In
the absence of renal biopsy as an option, anti-GBM antibody (option C) assay is the second most
accurate test to establish the diagnosis.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-120b4d598f8a","duplicate_sources":[{"record_id":"8f71d8085f45fd9cc301","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1923,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"8f71d8085f45fd9cc301","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1923,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 22-year-old man presents to the Emergency Department with cough and dyspnea of one week\nduration, as well as fatigue, decreased urine output and dark-colored urine. Physical examination is\notherwise inconclusive. Which one of the following is the single most accurate investigation to\nestablish a diagnosis?","options":{"A":"Chest X-ray.","B":"Renal biopsy.","C":"Anti-glomerular basement membrane antibody.","D":"Urine analysis.","E":"High-resolution CT (HRCT) scan of the chest"},"source_answer":"B","source_explanation":"In this patient, simultaneity of lung involvement symptoms (cough and dyspnea) and renal\ninvolvement symptoms makes Goodpasture syndrome, also called anti-glomerular basement\nmembrane disease (anti-GBM disease) the most likely diagnosis. The disease may affect all age\ngroups but is much more common in those younger than 30 years of age. Pulmonary\nmanifestations of the disease include shortness of breath, cough and sometimes excessive\nhemopysis due to alveolar hemorrhage.\nNOTE - Lung involvement, specifically alveolar hemorrhage, can be seen with other acute\nnephritides due to pulmonary edema, or due to lung involvement in ANCA positive and other\nforms of systemic vasculitis, and lupus. In the latter however, other clinical findings in addition\nto lung and kidney symptoms would be expected. For example, it is unlikely that lupus affects\nonly the lungs and the kidneys, whereas Goodpasture syndrome almost always affects the\nkidneys and the lungs only.\nFor this patient a urine analysis (option D) and chest x-ray (option A) should be order as the initial\nworkup. Urine analysis in patients with Goodpasture disease usually shows the typical picture of\nglomerulonephritis including proteinuria (usually not in nephrotic range), dysmorphic red cells,\nwhite cells, and red cell and granular casts. These findings, however, indicates glomerulonephritis\nwithout delineating a specific etiology. Chest X-ray in patients with the disease shows pulmonary\ninfiltrates which indicates pulmonary involvement but again without a specific cause. HRCT (option\nE) can be considered for a detailed assessment of the lungs.\nThe criterion standard for Goodpasture disease is detection of anti-GBM antibodies either in the\nserum or in the kidneys. Renal biopsy should be performed in all patients with suspected\nGoodpasture syndrome unless it is contraindicated because serologic assay is variable in such\npatients. Light microscopy of the specimen from biopsy often shows crescentic\nglomerulonephritis, whereas immunofluorescence microscopy reveals the pathognomonic finding\nof linear deposition of IgG along the glomerular capillaries and occasionally the distal tubules. In\nthe absence of renal biopsy as an option, anti-GBM antibody (option C) assay is the second most\naccurate test to establish the diagnosis.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","duration"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"120b4d598f8a40334f9243a0415d36ae36b14ab4","duplicate_group_id":"exact-120b4d598f8a","duplicate_sources":[{"record_id":"8f71d8085f45fd9cc301","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1923,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
