INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('09497815867bf80a59f0','Amedex 2023.pdf','1929','Mixed/Unclassified','A 75-year-old man presents to your practice with worsening low back pain for the last month. He
denies any trauma to the back, weight loss, lower extremity pins and needles, or bladder and bowel
control problems. He was concerned about prostate cancer last year and requested a prostate
cancer screening with PSA the result of which was normal. There is slight tenderness over the
lower back, but neurological examination is normal. Plain radiographs of the lower back show
sclerotic changes in lower lumbar vertebrae and the pelvis. Which one of the following is the most
appropraite next step in management?','{"A":"Serum PSA.","B":"Serum protein electrophoresis.","C":"Transrectal ultrasound (TRUS).","D":"Bone scan.","E":"MRI of the spine."}','A','The sclerotic changes of the vertebrae and pelvis in an elderly male patient suggest prostatic
cancer with bone metastasis as high probability. Metastatic bone lesions in prostate cancer are
typically sclerotic.
For this patient, a digital rectal exam (DRE) (not an option) is the most important step to take as is
repeating the serum PSA.
PSA (prostate specific antigen) is a glycoprotein produced predominantly by the prostate
epithelium. It circulates in both free and bound forms. Despite modifications to the interpretation of
the PSA test to improve its accuracy such as use of age-specific reference range, or attempts to
make it more sensitive and specific for detection of prostate cancer, this test may still
underdiagnose or overdiagnose prostate cancer. It is estimated that 20-25% of patients with
prostate cancer may have a PSA level of less than 4 ng/mL which was accepted as ‘normal value’
in the past. Reports show that some patients with prostate cancer have even PSA levels of less
than 1 ng/mL. On the other hand, some with PSA values greater than age-specific range reference
are found to not have prostate cancer; however, such increased levels still warrant a full
assessment to exclude prostate cancer.
For patients with abnormalities detected on DRE or with serum PSA greater than that expected for
their age, transrectal ultrasound (TRUS) examination (option C) and prostate biopsy are performed.
TRUS is not diagnostic for prostate cancer and its main use is guiding the biopsy.
Radioisotope bone scan is the most sensitive method for detecting bony metastases. Such
metastases are usually distributed in the axial rather than the appendicular skeleton. However, the
probability of a positive scan is very low if the PSA is less than 10 ng/mL. Based on current
recommendations, bone scans in these patients are unnecessary; therefore, the decision as to
bone scan (option D) is determined by the PSA levels.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-c3899806ba2d","duplicate_sources":[{"record_id":"09497815867bf80a59f0","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1929,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"09497815867bf80a59f0","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1929,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 75-year-old man presents to your practice with worsening low back pain for the last month. He\ndenies any trauma to the back, weight loss, lower extremity pins and needles, or bladder and bowel\ncontrol problems. He was concerned about prostate cancer last year and requested a prostate\ncancer screening with PSA the result of which was normal. There is slight tenderness over the\nlower back, but neurological examination is normal. Plain radiographs of the lower back show\nsclerotic changes in lower lumbar vertebrae and the pelvis. Which one of the following is the most\nappropraite next step in management?","options":{"A":"Serum PSA.","B":"Serum protein electrophoresis.","C":"Transrectal ultrasound (TRUS).","D":"Bone scan.","E":"MRI of the spine."},"source_answer":"A","source_explanation":"The sclerotic changes of the vertebrae and pelvis in an elderly male patient suggest prostatic\ncancer with bone metastasis as high probability. Metastatic bone lesions in prostate cancer are\ntypically sclerotic.\nFor this patient, a digital rectal exam (DRE) (not an option) is the most impo