INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('72472a896b4beafd0807','Amedex 2023.pdf','1933','Mixed/Unclassified','A 25-year-old man presents with a painless right scrotal lump which he noticed while taking a
shower three days ago. There is no tenderness or other abnormal findings expect asymptomatic
enlargement of the right testis. The epididymis and spermatic cord can be felt in their normal
positions. An ultrasound scan is performed which is shown in the accompanying photograph.
Which one of the following is the most appropriate next step in management?','{"A":"Reassurance.","B":"Measurement of serum alpha phetoprotein (AFP).","C":"Measurement of serum carcinoembryonic antigen (CEA).","D":"Trans-inguinal excision of the right testis.","E":"Trans-scrotal excision of the right testis."}','B','The photograph pictures the ultrasonographic view of the right testis, in which a lesion is seen. The
lesion is combination of both cystic and solid structures. A testicular lump in a young man is
testicular cancer until proven otherwise.
When testicular cancer is suspected on ultrasound, the next best step is always obtaining blood
sample for serum tumor markers. Three serum tumor markers have established roles in patients
with suspected testicular cancer: alpha fetoprotein (AFP), beta subunit of human chorionic
gonadotropin (beta-hCG), and lactate dehydrogenase (LDH).
Tumor markers differ by histological subtype of testicular malignancies. In pure seminoma
testicular cancers, AFP is never elevated and beta-hCG is elevated in fewer than 20% of patients. In
other histological subtypes, AFP and beta-hCG are elevated in 85% of patients.
Of the options only measurement of serum AFP can be correct as the next best step in
management. However, the best option would recommend both AFP ans beta-hCG.
Other measures to conisder prior to surgery are:','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-c70e8a859460","duplicate_sources":[{"record_id":"72472a896b4beafd0807","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1933,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"72472a896b4beafd0807","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1933,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 25-year-old man presents with a painless right scrotal lump which he noticed while taking a\nshower three days ago. There is no tenderness or other abnormal findings expect asymptomatic\nenlargement of the right testis. The epididymis and spermatic cord can be felt in their normal\npositions. An ultrasound scan is performed which is shown in the accompanying photograph.\nWhich one of the following is the most appropriate next step in management?","options":{"A":"Reassurance.","B":"Measurement of serum alpha phetoprotein (AFP).","C":"Measurement of serum carcinoembryonic antigen (CEA).","D":"Trans-inguinal excision of the right testis.","E":"Trans-scrotal excision of the right testis."},"source_answer":"B","source_explanation":"The photograph pictures the ultrasonographic view of the right testis, in which a lesion is seen. The\nlesion is combination of both cystic and solid structures. A testicular lump in a young man is\ntesticular cancer until proven otherwise.\nWhen testicular cancer is suspected on ultrasound, the next best step is always obtaining blood\nsample for serum tumor markers. Three serum tumor markers have established roles in patients\nwith suspected testicular cancer: alpha fetoprotein (AFP), beta subunit of human chorionic\ngonadotropin (beta-hCG), and lactate dehydrogenase (LDH).\nTumor markers differ by histological subtype of testicular malignancies. In pure seminoma\ntesticular cancers, AFP is never elevated and beta-hCG is elevated in fewer than 20% of patients. In\nother histological subtypes, AFP and beta-hCG are elevated in 85% of patients.\nOf the options only measurement of serum AFP can be correct as the next best step in\nmanagement. However, the best option would recommend both AFP ans beta-hCG.\nOther measures to conisder prior to surgery are:","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"c70e8a85946024e2489ff0ca8c319b7ac183a674","duplicate_group_id":"exact-c70e8a859460","duplicate_sources":[{"record_id":"72472a896b4beafd0807","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1933,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_js