INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b392a6d125640aca8053','Amedex 2023.pdf','1938','Mixed/Unclassified','A 47-year-old man presents to your practice with a scrotal swelling. The swelling is not painful and
has been there for the past 4 months. He does not feel bothered with the swelling and has just
come to see you because her wife has forced him to. On examination, there is a non-tender
swelling in the left testis. Ultrasonography shows the mass to be cyst within the right left
testis. Which one of the following would be the next best step in management?','{"A":"Surgery.","B":"Biopsy through inguinal route.","C":"Biopsy through scrotum.","D":"Measuring serum tumour makers (alpha-phetoprotein and beta-hCG).","E":"Reassurance."}','D','Testicular cystic lesions are relatively common findings on testicular ultrasound. The underlying
pathology ranges from benign to malignant and may include:
Simple testicular cyst
Tunica albuginea cyst
Cystic transformation of rete testis (intratesticular tubular ectasia)
Intratesticular spermatocele
Intratesticular varicocele
Testicular epidermoid cyst
Cystadenoma of the rete testis
Testicular abscess
Testicular tumors
Over 23% of testicular cysts are malignant. For this reason, malignancy should be excluded by
serum tumor markers as the most appropriate next step in management once a testicular cyst is
found on ultrasound. Three serum tumor markers have established role in testicular cancer:
1. alpha fetoprotein (AFP)
2. beta subunit of human chorionic gonadotropin (beta-hCG)
3. lactate dehydrogenase (LDH).
In seminoma testicular cancer, AFP is never elevated and beta-hCG is elevated in fewer than 20% of
patients. In non-seminoma testicular cancers, AFP and beta-hCG are elevated in 85% of patients.
(Option A) Surgery for orchiectomy is considered after investigations establish a diagnosis of
testicualr cancer. Without a definite diagnosis, surgery is not indicated for now.
(Option B) Biopsy through inguinal approach is inappropriate at this stage and before tumor marker
assay. 
(Option C) Testicular tumors are never resected through scrotal excisions.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-2cace1adcdda","duplicate_sources":[{"record_id":"b392a6d125640aca8053","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1938,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"b392a6d125640aca8053","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1938,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 47-year-old man presents to your practice with a scrotal swelling. The swelling is not painful and\nhas been there for the past 4 months. He does not feel bothered with the swelling and has just\ncome to see you because her wife has forced him to. On examination, there is a non-tender\nswelling in the left testis. Ultrasonography shows the mass to be cyst within the right left\ntestis. Which one of the following would be the next best step in management?","options":{"A":"Surgery.","B":"Biopsy through inguinal route.","C":"Biopsy through scrotum.","D":"Measuring serum tumour makers (alpha-phetoprotein and beta-hCG).","E":"Reassurance."},"source_answer":"D","source_explanation":"Testicular cystic lesions are relatively common findings on testicular ultrasound. The underlying\npathology ranges from benign to malignant and may include:\nSimple testicular cyst\nTunica albuginea cyst\nCystic transformation of rete testis (intratesticular tubular ectasia)\nIntratesticular spermatocele\nIntratesticular varicocele\nTesticular epidermoid cyst\nCystadenoma of the re