INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('c0390511e53d16a76bbf','Amedex 2023.pdf','1940','Mixed/Unclassified','A 17-year-old boy presents to the emergency department with a 2-hour history of a painful and
tender right testis. On examination, the scrotum is tender and swollen. Spermatic cord is thickened
and can be moved above the lump. Which one of the following is the next best step in
management?','{"A":"Surgery.","B":"Ultrasound.","C":"Urine microscopy and culture.","D":"Full blood count.","E":"Technetium scan."}','A','A painful scrotum should be taken seriously because the outcome of an untreated testicular
torsion can be catastrophic. The testis can be infarcted in 4 to 6 hours.
With physical findings of a swollen, tender and firm hemiscrotum with a short and thickened
spermatic cord the patient should immediately be taken to the operating room. No male younger
than 18 years should be considered to have epididymo-orchitis until the testis has been exposed at
operating room and torsion is excluded.
(Option B) The role of ultrasound in distinguishing between testicular torsion and epididymo-
orchitis is controversial, as it cannot reliably detect changes that are diagnostic for an early torsion.
(Options C and D) Once torsion of testis has been ruled out, full blood count, urine microscopy and
Chlamydia testing are performed to clinch other possible diagnoses.
(Option E) A technetium-99 m scan can differentiate between the two conditions. In testicular
torsion the testis is avascular, while it is hyperemic in epididymo-orchitis. However, with acute
scrotal pain in a young male, the diagnosis is testicular torsion until proven otherwise by surgival
exploration. No time should be wasted on diagnostic procedures.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"793","duplicate_group_id":"exact-5bbd28cfe049","duplicate_sources":[{"record_id":"c0390511e53d16a76bbf","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1940,"source_qid":"793"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"c0390511e53d16a76bbf","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1940,"source_qid":"793","domain_hint":"Mixed/Unclassified","stem":"A 17-year-old boy presents to the emergency department with a 2-hour history of a painful and\ntender right testis. On examination, the scrotum is tender and swollen. Spermatic cord is thickened\nand can be moved above the lump. Which one of the following is the next best step in\nmanagement?","options":{"A":"Surgery.","B":"Ultrasound.","C":"Urine microscopy and culture.","D":"Full blood count.","E":"Technetium scan."},"source_answer":"A","source_explanation":"A painful scrotum should be taken seriously because the outcome of an untreated testicular\ntorsion can be catastrophic. The testis can be infarcted in 4 to 6 hours.\nWith physical findings of a swollen, tender and firm hemiscrotum with a short and thickened\nspermatic cord the patient should immediately be taken to the operating room. No male younger\nthan 18 years should be considered to have epididymo-orchitis until the testis has been exposed at\noperating room and torsion is excluded.\n(Option B) The role of ultrasound in distinguishing between testicular torsion and epididymo-\norchitis is controversial, as it cannot reliably detect changes that are diagnostic for an early torsion.\n(Options C and D) Once torsion of testis has been ruled out, full blood count, urine microscopy and\nChlamydia testing are performed to clinch other possible diagnoses.\n(Option E) A technetium-99 m scan can differentiate between the two conditions. In testicular\ntorsion the testis is avascular, while it is hyperemic in epididymo-orchitis. However, with acute\nscrotal pain in a young male, the diagnosis is testicular torsion until proven otherwise by surgival\nexploration. No time should be wasted on diagnostic procedures.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"5bbd28cfe049402daba7f0b801aa9267410a3d8f","duplicate_group_id":"exact-5bbd28cfe049","duplicate_sources":[{"record_id":"c0390511e53d16a76bbf","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1940,"source_qid":"793"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz