INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('8c2c28838ad568ca8ac2','Amedex 2023.pdf','1941','Mixed/Unclassified','A 20-year-old man patient presents to your clinic with painless scrotal swelling. Ultrasound shows
a solid mass in the left testis. Which one of the following is the next best step in management?','{"A":"Fine needle aspiration cytology (FANC).","B":"Surgical exploration.","C":"CT scan of the chest.","D":"Serum lactate dehydrogenase (LDH).","E":"Serum beta-hCG and alpha fetoprotein (AFP)."}','E','All scrotal lumps in a young male is malignancy until proven otherwise, especially if painless.
Ultrasound is the initial investigation of choice for assessment of a scrotal lump. If a lesion within
the testis is found on ultrasound, malignancy should come at the top of the differentials list, and
blood sample be obtained for serum tumor markers. Tumor markrs used for testicular cancer are
alpha feto-protein (AFP) , beta hCG and lactate dehydrogenase (LDH). LDH is usually elevated in
metastatiic tumors. 
In seminoma testicular cancers, AFP is never elevated and beta-hCG is elevated in less than 20% of
patients. In non-seminoma testicular cancer, however, AFP and beta hCG are elevated in 85% of
patients. Serum tumor markers, especially AFP and beta hCG, can provide evidence for the initial
diagnosis of a testicular cancer, and are useful for assessment of the prognosis and risk
stratification.
(Option A) Fine needle aspiration is not recommended for testicular cancers due to potential risk of
tumor implantation in the scrotal wall.
(Option B) Surgical exploration is contraindicated due to the risk of tumor spread. Any scrotal
incision should be avoided. Once the diagnosis of testicular cancer is established, orchiectomy
through inguinal approach is the best initial treatment.
(Option C) CT scan of the chest is helpful for tumor staging once the diagnosis is established.
(Option D) LDH levels raise when the tumor has metastasized and is not elevated early in the
course of the disease when no metastasis has occurred; therefore, this marker alone is not often
diagnostic.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"794","duplicate_group_id":"exact-1c7b843b246c","duplicate_sources":[{"record_id":"8c2c28838ad568ca8ac2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1941,"source_qid":"794"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"8c2c28838ad568ca8ac2","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1941,"source_qid":"794","domain_hint":"Mixed/Unclassified","stem":"A 20-year-old man patient presents to your clinic with painless scrotal swelling. Ultrasound shows\na solid mass in the left testis. Which one of the following is the next best step in management?","options":{"A":"Fine needle aspiration cytology (FANC).","B":"Surgical exploration.","C":"CT scan of the chest.","D":"Serum lactate dehydrogenase (LDH).","E":"Serum beta-hCG and alpha fetoprotein (AFP)."},"source_answer":"E","source_explanation":"All scrotal lumps in a young male is malignancy until proven otherwise, especially if painless.\nUltrasound is the initial investigation of choice for assessment of a scrotal lump. If a lesion within\nthe testis is found on ultrasound, malignancy should come at the top of the differentials list, and\nblood sample be obtained for serum tumor markers. Tumor markrs used for testicular cancer are\nalpha feto-protein (AFP) , beta hCG and lactate dehydrogenase (LDH). LDH is usually elevated in\nmetastatiic tumors. \nIn seminoma testicular cancers, AFP is never elevated and beta-hCG is elevated in less than 20% of\npatients. In non-seminoma testicular cancer, however, AFP and beta hCG are