INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('31b457d4f3f159b13814','Amedex 2023.pdf','1942','Mixed/Unclassified','A 42-year-old man presents to your clinic with history of a slowly-enlarging painless scrotal mass
over the past m onths. He has previous history of unilateral cryptorchidism which required
orchiopexy. On examination, a solid scrotal lump is palpated. Which one of the following would be
the next best step in management?','{"A":"Measuring serum alpha fetoprotein.","B":"Measuring serum human beta chorionic gonadotropin (βHCG).","C":"CT scan of the abdomen and pelvis.","D":"Ultrasonography of the scrotum.","E":"Scrotal needle biopsy."}','D','All solid scrotal lumps should be considered malignant until proven otherwise. In approach to
scrotal masses the most appropriate next step is to request an ultrasound to further evaluate the
scrotal mass.
Ultrasound of the testes can reliably diagnose the testicular tumor with considerable precision and
can also detect any invasion of the tunica albuginea.
This man also has undergone orchipexy that is a risk factor for development of testicular cancer.
Risk factors of development of testicular cancer include personal or family history of any of the
following:
Cryptorchidism (undescended testes)
Orchiopexy
Testicular atrophy
Previous testicular cancer
(Options A and B) Tumor markers (alpha fetoprotein and beta HCG) are not requested
unless ultrasound suggests cancer.
(Option C) CT scan of the abdomen, pelvis and chest is done for staging purposes and only
considered after confirmed diagnosis of testicular malignancy.
(Option E) Needle scrotal biopsy should be avoided because of potential risk of tumor implanting
malignant cells in the scrotal wall.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-9cf5950237bd","duplicate_sources":[{"record_id":"31b457d4f3f159b13814","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1942,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"31b457d4f3f159b13814","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1942,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 42-year-old man presents to your clinic with history of a slowly-enlarging painless scrotal mass\nover the past m onths. He has previous history of unilateral cryptorchidism which required\norchiopexy. On examination, a solid scrotal lump is palpated. Which one of the following would be\nthe next best step in management?","options":{"A":"Measuring serum alpha fetoprotein.","B":"Measuring serum human beta chorionic gonadotropin (βHCG).","C":"CT scan of the abdomen and pelvis.","D":"Ultrasonography of the scrotum.","E":"Scrotal needle biopsy."},"source_answer":"D","source_explanation":"All solid scrotal lumps should be considered malignant until proven otherwise. In approach to\nscrotal masses the most appropriate next step is to request an ultrasound to further evaluate the\nscrotal mass.\nUltrasound of the testes can reliably diagnose the testicular tumor with considerable precision and\ncan also detect any invasion of the tunica albuginea.\nThis man also has undergone orchipexy that is a risk factor for development of testicular cancer.\nRisk factors of development of testicular cancer include personal or family history of any of the\nfollowing:\nCryptorchidism (undescended testes)\nOrchiopexy\nTesticular atrophy\nPrevious testicular cancer\n(Options A and B) Tumor markers (alpha fetoprotein and beta HCG) are not requested\nunless ultrasound suggests cancer.\n(Option C) CT scan of the abdomen, pelvis and chest is done for staging purposes and only\nconsidered after confirmed diagnosis of testicular malignancy.\n(Option E) Needle scrotal biopsy should be avoided because of potential risk of tumor implanting\nmalignant cells in the scrotal wall.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"9cf5950237bd7d8f5944391650544b45368b5bce","duplicate_group_id":"exact-9cf5950237bd","duplicate_sources":[{"record_id":"31b457d4f3f159b13814","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1942,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_v