INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('8390863e40d766c3bce4','Amedex Eye + Ent 2025.pdf','5','Ophthalmology/ENT','A 65-year-old woman presents to the emergency
department with sudden onset decrease in visual
acuity and floaters in the visual field of her right
eye. The eye appears normal on inspection, and is
not painful. Which one of the following could be
