INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('afeef15fa0054ec62117','Amedex Eye + Ent 2025.pdf','150','Ophthalmology/ENT','Jane is 67 years old and a known case of type 2
diabetes mellitus for the past few years. She has
presented to your clinic in distress because she
has started bumping into objects since this
morning. She also says that she has been seeing
floaters and flies in front of her eyes for the past
three days. Eye examination reveals vision loss
and decreased red reflex of the right eye. The right
retina cannot be visualized. The vision of the left
eye is preserved; however, there are retinal
changes consistent with pre-proliferative diabetic
retinopathy. Which one of the following could be
